            'field_closure' => 'समाप्ति पर श्रेणी',
            'field_closure_desc' => 'यह असल में क्या निकला। टिकट बंद होने पर वही सूची दोबारा पूछी जाती है — ज़्यादातर बार विश्लेषक बस उसकी पुष्टि करता है। यह रखने लायक है: यही आपको बताता है कि आपकी 37 "printer problems" में से 12 असल में नेटवर्क की थीं।',
            'field_resolution' => 'समाधान कोड',
            'field_resolution_desc' => 'टिकट कैसे खत्म हुआ, जो यह किस बारे में था इससे अलग सवाल है — "Training given", "No fault found"।',
