        'intros' => [
            'checklists' => 'एक चेकलिस्ट चरणों को अनिवार्य चिह्नित कर सकती है। यह तय करता है कि अगर कोई उन चरणों को टिक करने से पहले टिकट बंद करे तो क्या होता है।',
            'mandatory_fields' => 'चुनें कि टिकट बंद होने से पहले कौन-सी टिकट फ़ील्ड भरी जानी चाहिए, और अगर कोई उनमें से किसी को खाली रखकर टिकट बंद करे तो क्या होता है। यह नियम हर जगह लागू होता है जहाँ टिकट बंद किया जा सकता है: टिकट स्क्रीन, बल्क एक्शन, REST API और वर्कफ़्लो।',
            'departments' => 'विभाग टिकटों को समूहित करते हैं और आपके संगठन के सही हिस्से तक रूट करते हैं — वे बनाएँ जिन्हें आपका सर्विस डेस्क काम वर्गीकृत करने और सौंपने के लिए उपयोग करता है।',
            'teams' => 'टीमें तय करती हैं कि विश्लेषक किन विभागों तक पहुँच सकते हैं। विभागों को टीमों को सौंपें, फिर विश्लेषकों को टीमों को सौंपकर उनकी पहुँच नियंत्रित करें।',
            'ticket_types' => 'टिकट प्रकार बताते हैं कि अनुरोध क्या है (जैसे Incident, Service Request) — वे प्रकार परिभाषित करें जिन्हें विश्लेषक टिकट पर सेट कर सकते हैं।',
            'ticket_origins' => 'टिकट स्रोत यह दर्ज करते हैं कि टिकट कैसे आया (जैसे Email, Phone, Portal) — वे स्रोत परिभाषित करें जिनमें से विश्लेषक चुन सकते हैं।',
            'mailboxes' => 'मेलबॉक्स FreeITSM को ईमेल खातों से जोड़ते हैं ताकि आने वाले संदेश टिकट बनें और जवाब वापस बाहर जाएँ — वे जोड़ें और प्रमाणित करें जिन्हें आपका सर्विस डेस्क मॉनिटर करता है।',
            'privacy' => 'एक टिकट में केवल उस व्यक्ति के साथ आपकी बातचीत नहीं होती जिसने इसे उठाया। किसी आपूर्तिकर्ता को फ़ॉरवर्ड करना, या किसी सहकर्मी को Cc करना, उस संदेश को उसी टिकट पर डाल देता है — और उनका जवाब भी वहीं आता है। यह तय करता है कि अनुरोधकर्ता इसमें से कितना सेल्फ-सर्विस पोर्टल में देखता है।',
            'indexing' => 'अटैचमेंट के अंदर का टेक्स्ट पढ़ा जाता है ताकि इसे खोजा जा सके। Word, Excel, PowerPoint और प्लेन टेक्स्ट फ़ाइलें FreeITSM खुद, आने के तुरंत बाद पढ़ लेता है। PDF, पुरानी Office फ़ाइलों और स्कैन किए गए दस्तावेज़ों के लिए एक अलग डॉक्यूमेंट-रीडिंग सर्विस चाहिए — इसे <strong>System &rarr; Integrations &rarr; Apache Tika</strong> के अंतर्गत सेट करें — और चूँकि इनमें बहुत ज़्यादा समय लगता है, ये बैकग्राउंड में पढ़े जाते हैं। ये दो स्विच तय करते हैं कि यह बैकग्राउंड काम कब होता है।',
            'merge_behaviour' => 'जब दो टिकट एक ही चीज़ निकलते हैं, तो कोई विश्लेषक उन्हें मर्ज कर सकता है। ये सेटिंग्स तय करती हैं कि इसका आपके अनुरोधकर्ताओं के पास मौजूद टिकट संदर्भों पर क्या असर होता है, और बातचीत का क्या होता है। ये सभी पर लागू होती हैं — मर्ज करने से ग्राहक को जो दिखता है वह बदल जाता है, इसलिए एक ही मेलबॉक्स के दो विश्लेषक इस पर असहमत नहीं हो सकते।',
            'reply_templates' => 'तैयार जवाब जिन्हें आपके विश्लेषक दोबारा टाइप करने के बजाय जवाब में डाल सकते हैं। ये साझा वाले हैं जो पूरी टीम देखती है — किसी विश्लेषक के अपने निजी टेम्पलेट जवाब विंडो से सहेजे जाते हैं और यहाँ सूचीबद्ध नहीं होते।',
            'rota_shifts' => 'शिफ्ट वे कार्य-पैटर्न टेम्पलेट हैं (जैसे Early, Late, On-call) जो विश्लेषकों को स्टाफ़ रोटा पर असाइन किए जाते हैं — रोटा बनाने से पहले इन्हें यहाँ परिभाषित करें।',
            'analysts' => 'विश्लेषक वे स्टाफ़ हैं जो लॉग इन करके टिकट पर काम करते हैं — उन्हें जोड़ें, पासवर्ड रीसेट करें, और उनकी पहुँच नियंत्रित करने के लिए टीमों को सौंपें।',
            'general' => 'सामान्य सेटिंग्स सिस्टम-व्यापी विकल्पों को नियंत्रित करती हैं जैसे सर्विस डेस्क का नाम और डिफ़ॉल्ट — इन्हें अपने संगठन के अनुसार समायोजित करें।',
            'statuses' => 'वर्कफ़्लो स्थितियाँ जिनमें एक टिकट हो सकता है। <em>Closed</em> के रूप में चिह्नित स्थितियाँ समाप्ति के रूप में गिनी जाती हैं — रिपोर्ट, वॉचटावर काउंटर और असाइन करने पर बंद-होने-की-तारीख के ऑटो-सेट द्वारा उपयोग की जाती हैं। ठीक एक स्थिति नए टिकटों के लिए डिफ़ॉल्ट होती है।',
