            'calendars_heading' => 'व्यावसायिक कैलेंडर',
            'calendars_intro' => 'कार्य-घंटे, टाइमज़ोन, और अवकाश सूचियाँ परिभाषित करें। कैलेंडर का संदर्भ SLA लक्ष्यों (ऊपर) और अलग-अलग प्राथमिकताओं द्वारा दिया जाता है। एक कैलेंडर नई प्राथमिकताओं के लिए डिफ़ॉल्ट होता है।',
