            'col_actions' => 'क्रियाएँ',
            'notifs_heading' => 'ब्रीच सूचनाएँ',
            'notifs_info' => '<strong style="display:block;margin-bottom:6px;font-size:14px;">सूचना नियम कैसे काम करते हैं</strong>हर नियम के चार हिस्से होते हैं: एक <strong>स्कोप</strong>, एक <strong>ट्रिगर</strong>, एक <strong>लक्ष्य</strong>, और <strong>प्राप्तकर्ताओं</strong> की एक सूची।<br><br><strong>स्कोप</strong> या तो <em>डिफ़ॉल्ट</em> हो सकता है (नियम हर विभाग के टिकटों पर लागू होता है) या कोई <em>विशिष्ट विभाग</em> (नियम केवल उसी विभाग के टिकटों पर लागू होता है)।<br>जब किसी टिकट का आकलन किया जा रहा हो, तो सिस्टम पहले उसके विभाग से मेल खाता नियम ढूँढता है &mdash; अगर एक मौजूद है, तो वही नियम जीतता है और डिफ़ॉल्ट को नज़रअंदाज़ किया जाता है। अगर कोई विभाग-विशिष्ट नियम नहीं है, तो डिफ़ॉल्ट नियम उपयोग होता है। इस तरह आप हर विभाग को कवर करने वाले समझदार डिफ़ॉल्ट सेट कर सकते हैं, फिर वहाँ अपवाद बना सकते हैं जहाँ किसी टीम की एस्केलेशन ज़रूरतें अलग हों।<br><br><strong>ट्रिगर</strong> या तो <em>चेतावनी</em> होता है (टिकट चेतावनी सीमा पार कर चुका है &mdash; संभावित ब्रीच नज़दीक आ रहा है) या <em>ब्रीच</em> (टिकट अब अपना SLA लक्ष्य पार कर चुका है &mdash; वास्तविक ब्रीच)। हर एक अपना अलग नियम है, इसलिए आप चेतावनी और ब्रीच के लिए अलग-अलग लोगों को सूचित कर सकते हैं।<br><br><strong>लक्ष्य</strong> यह है कि किस SLA घड़ी पर नज़र रखनी है &mdash; <em>प्रतिक्रिया</em>, <em>समाधान</em>, या <em>दोनों</em>।<br><br><strong>प्राप्तकर्ता</strong> इनमें से किसी भी संयोजन हो सकते हैं: टिकट का मौजूदा असाइनी, टिकट की विभाग टीमों का हर विश्लेषक, एक नामित विश्लेषक, और/या फ्री-फ़ॉर्म ईमेल पतों की एक सूची (शेयर्ड इनबॉक्स या Slack/Teams ईमेल ब्रिज के लिए उपयोगी)।<br><br><strong style="color:var(--warning-text, #92400e);">कोई नियम नहीं = कोई ईमेल नहीं।</strong> टिकट ब्रीच होने पर भी, जब तक आप कम से कम एक नियम नहीं जोड़ते, कुछ नहीं चलता (सब कुछ कवर करने के लिए डिफ़ॉल्ट-स्कोप की चेतावनी + ब्रीच जोड़ी से शुरू करें)।',
