            'existing_note' => '<strong>पहले से नंबर किया गया कुछ भी नहीं बदलता।</strong> मौजूदा टिकट अपना संदर्भ बनाए रखते हैं, और FreeITSM ने अब तक जो भी संदर्भ जारी किया है वह काम करता रहता है &mdash; पुराने ईमेल के जवाबों में भी। अगर आप मौजूदा टिकटों को भी दोबारा नंबर देना चाहते हैं, तो नीचे इसके लिए एक टूल है। <strong>अंक खत्म नहीं होंगे:</strong> आपने जो चौड़ाई चुनी है वह न्यूनतम है, इसलिए टिकट 1,000,001 टूटने के बजाय बस एक अंक लंबा हो जाता है।',
