            'renumber_safety' => '<strong>पुराने संदर्भ काम करते रहते हैं।</strong> किसी टिकट को अब तक मिला हर नंबर याद रखा जाता है, इसलिए पुराने नंबर का हवाला देने वाले ईमेल का जवाब भी सही टिकट पर पहुँचता है &mdash; ठीक वैसे ही जैसे टिकट मर्ज होने पर होता है। कोई रिटायर हुआ नंबर किसी दूसरे टिकट को कभी नहीं दिया जाता। हालाँकि, इसे पूर्ववत नहीं किया जा सकता, इसलिए पहले पूर्वावलोकन देखें।',
