            'ai_heading' => 'AI पठन सहायक',
            'ai_desc' => 'वैकल्पिक, और जब तक आप चालू न करें तब तक बंद: इस पेज पर बाकी सब कुछ के उलट, ये आपके अपने AI प्रदाता का उपयोग करते हैं और प्रति उपयोग पैसे खर्च करते हैं। प्रदाता, मॉडल और API key एक बार उत्तर सफ़ाई टैब पर कॉन्फ़िगर की जाती है। AI जो भी लिखे वह टिकट की जगह कभी नहीं लेता — बातचीत पूरी तरह वहीं बनी रहती है जहाँ है।',
            'ai_summary_label' => 'हर टिकट के ऊपर एक छोटा AI सारांश रखें',
            'ai_summary_help' => 'कुछ पंक्तियाँ जो बताती हैं कि टिकट कहाँ खड़ा है, माँगने पर लिखी जाती हैं और अद्यतन रखी जाती हैं। यह हमेशा दिखाता है कि यह कब लिखा गया, इसने कितना पढ़ा, और तब से बातचीत कितनी आगे बढ़ी है। हर वर्शन रखा जाता है, इसलिए एक कमज़ोर सारांश किसी बेहतर सारांश को कभी नष्ट नहीं करता।',
            'ai_auto_label' => 'इतने नए संदेशों के बाद इसे अपने आप रीफ्रेश करें',
            'ai_auto_help' => '0 का मतलब है कभी नहीं — तब Refresh बटन ही एकमात्र तरीका है, और बिना किसी के माँगे कभी कोई शुल्क नहीं लगता। रीफ्रेश तभी होता है जब कोई विश्लेषक टिकट खोलता है, इसलिए जिस व्यस्त कतार को कोई नहीं पढ़ रहा उसका कुछ खर्च नहीं होता।',
            'ai_max_label' => 'पढ़े जाने वाले संदेश',
            'ai_max_help' => 'सारांश कितना पीछे तक पढ़ता है। एक लंबे टिकट को उसके सबसे हाल के छोर से पढ़ा जाता है, और सारांश यह बताता है, बजाय ऐसी शुरुआत बताने के जिसे उसने कभी देखा ही नहीं।',
            'ai_notes_label' => 'इसे आंतरिक नोट पढ़ने दें',
            'ai_notes_help' => 'आंतरिक नोट अक्सर बताते हैं कि असल में क्या आज़माया गया। ये वैसे भी केवल स्टाफ़ के लिए हैं — सारांश किसी अनुरोधकर्ता को कभी नहीं दिखाया जाता — लेकिन अगर आपके डेस्क के नोट ऐसी बातें रखते हैं जो इससे बाहर नहीं जानी चाहिए तो इसे बंद कर दें।',
            'ai_read_label' => 'टिकट पर "Read it for me" उपलब्ध कराएँ',
            'ai_read_help' => 'एक बटन जो पूरा टिकट पढ़ता है और आपको इसकी जानकारी देता है: क्या हुआ, क्या अनसुलझा है, और आगे क्या किया जाएगा। माँगे जाने पर एक बार पढ़ा जाता है, कहीं संग्रहीत नहीं होता।',
            'reopen_help' => 'यह जहाँ भी अनुरोधकर्ता वापस आए वहाँ लागू होता है — सेल्फ-सर्विस पोर्टल, आपके नोटिफिकेशन ईमेल का जवाब, WhatsApp या वेब चैट। टिकट आपकी पहली खुली स्थिति में वापस चला जाता है। केवल बंद के रूप में चिह्नित स्थिति वाले टिकट प्रभावित होते हैं (कौन सी स्थितियाँ वे हैं यह Statuses के अंतर्गत सेट करें)।',
        ],
        'privacy' => [
            'third_party_label' => 'अनुरोधकर्ता के अलावा किसी और को भेजे गए संदेश',
            'opt_hide' => 'अनुरोधकर्ता से इन्हें छिपाएँ',
            'opt_hide_help' => 'संदेश और उसके अटैचमेंट अनुरोधकर्ता के पोर्टल में बिल्कुल नहीं दिखते। अनुशंसित: ज़्यादातर लोग मान लेते हैं कि किसी टिकट को आपूर्तिकर्ता को फ़ॉरवर्ड करना निजी है।',
            'opt_no_attachments' => 'संदेश दिखाएँ, लेकिन उसके अटैचमेंट नहीं',
            'opt_no_attachments_help' => 'अनुरोधकर्ता देख सकता है कि आपने किसी और से संपर्क किया और क्या लिखा गया, लेकिन कोई संलग्न फ़ाइल डाउनलोड नहीं कर सकता।',
            'opt_show' => 'सब कुछ दिखाएँ',
            'opt_show_help' => 'अनुरोधकर्ता पूरा टिकट बिल्कुल वैसे ही देखता है जैसे आपके विश्लेषक देखते हैं, फ़ॉरवर्ड और थर्ड-पार्टी जवाबों सहित। यह सेटिंग बनने से पहले का व्यवहार था।',
            'always_visible_note' => '<strong>अनुरोधकर्ता को हमेशा दिखता है:</strong> उनके अपने संदेश, और उन्हें संबोधित कोई भी जवाब। <strong>कभी नहीं दिखता:</strong> आंतरिक नोट — ये इस सेटिंग से बेपरवाह पोर्टल से छिपे रहते हैं। WhatsApp और वेब चैट पर संदेश हमेशा दिखाए जाते हैं, क्योंकि वे बातचीत परिभाषा से ही अनुरोधकर्ता और आपके डेस्क के बीच होती है।',
            'timezone' => 'टाइमज़ोन',
            'timezone_help' => 'पूरे सिस्टम में तारीख़ और समय दिखाने के लिए उपयोग होता है।',
        ],
        'reply_cleanup' => [
            'intro1' => 'जब कोई विश्लेषक टिकट कंपोज़ मोडल में एक कच्चा जवाब टाइप करता है, तो <strong>✨ Cleanup</strong> बटन इसे एक ठीक से फ़ॉर्मैट किए गए ईमेल के रूप में फिर से लिखता है — एक "Dear [name]," अभिवादन जोड़कर, व्याकरण ठीक करके, नीचे आपके चुने टोन को लागू करके, और "Kind regards," के साथ साइन-ऑफ करके। यह तकनीकी विवरण गढ़ेगा <strong>नहीं</strong> और न ही सामग्री को भरेगा।',
            'intro2' => 'यह फ़ीचर अपनी खुद की Anthropic API key उपयोग करता है (RFP AI और Knowledge AI से अलग) ताकि इसका उपयोग Anthropic बिलिंग डैशबोर्ड पर एक अलग लाइन के रूप में दिखे।',
            'tone' => 'टोन',
            'tone_friendly' => 'दोस्ताना (डिफ़ॉल्ट)',
            'tone_formal' => 'औपचारिक',
            'tone_brief' => 'संक्षिप्त',
            'tone_help' => 'जब तक यहाँ न बदला जाए, हर cleanup पर लागू होता है।',
            'custom_label' => 'कस्टम निर्देश <span style="color: #999; font-weight: normal;">(वैकल्पिक)</span>',
            'custom_placeholder' => 'जैसे हमेशा \'Many thanks,\' के साथ साइन-ऑफ करें&#10;कंपनी को \'BillCorp\' के रूप में संदर्भित करें&#10;पूरे टेक्स्ट में British English स्पेलिंग उपयोग करें',
            'custom_help' => 'दाईं ओर दिखाए गए सिस्टम प्रॉम्प्ट में जोड़ा जाता है। संगठन-विशिष्ट बदलावों (साइन-ऑफ वैरिएशन, कंपनी का नाम, भाषा प्राथमिकताएँ) के लिए इसका उपयोग करें। सख्त सुरक्षा नियम और आउटपुट फ़ॉर्मैट फिर भी प्राथमिकता में रहेंगे।',
            'prompt_summary' => 'सिस्टम प्रॉम्प्ट देखें (केवल-पढ़ने योग्य)',
            'prompt_panel_intro' => 'यह वह पूरा सिस्टम प्रॉम्प्ट है जो हर cleanup पर Claude को भेजा जाता है। अभिवादन का नाम प्रति टिकट अलग होता है; टोन बाईं ओर आपकी पसंद को दिखाता है। आपके कस्टम निर्देश (अगर कोई हों) रनटाइम पर अंत में जोड़े जाते हैं — वे यहाँ नहीं दिखते, उन्हें बाईं ओर के टेक्स्टएरिया में संपादित करें।',
        ],
        'csat_tab' => [
            'intro1' => 'जब कोई टिकट बंद होता है, तो अनुरोधकर्ता को अनुभव को 1&ndash;5 में रेट करने के लिए एक छोटा सर्वेक्षण ईमेल भेजें। प्रतिक्रियाएँ उस विश्लेषक के खिलाफ दर्ज होती हैं जिसने टिकट बंद किया था ताकि आप प्रति-विश्लेषक CSAT रुझान निकाल सकें, और डैशबोर्ड पर एक विजेट के रूप में लाइव रहती हैं।',
            'intro2' => 'सर्वेक्षण ईमेल <a href="#" onclick="event.preventDefault();switchTab(\'email-templates\');">Email templates</a> के अंतर्गत कॉन्फ़िगर होता है &mdash; इवेंट <strong>CSAT survey</strong> के साथ एक टेम्पलेट बनाएँ और एक-बार वाला रेटिंग URL डालने के लिए बॉडी में <code>[csat_link]</code> एम्बेड करें।',
            'mode_off' => 'बंद',
