            'mode_auto' => 'बंद होने पर ऑटो',
            'mode_auto_help' => 'टिकट के किसी भी बंद स्थिति में जाने पर एक सर्वेक्षण अपने आप भेजा जाता है।',
            'mode_manual' => 'केवल मैनुअल',
            'mode_manual_help' => 'जब विश्लेषक पूछना चाहते हैं तो वे टिकट टूलबार से <em>Feedback</em> पर क्लिक करते हैं।',
            'delay_help' => 'बंद होने के बाद भेजने से पहले इतने मिनट प्रतीक्षा करें। <code>0</code> = तुरंत। उपयोगी अगर आप चाहते हैं कि रेट करने के लिए कहे जाने से पहले उपयोगकर्ता यह पुष्टि कर ले कि फ़िक्स असल में टिका रहा।',
            'one_per_ticket' => 'प्रति टिकट एक सर्वेक्षण',
            'one_per_ticket_help' => 'चालू होने पर, फिर से खोले गए और फिर बंद किए गए टिकट को दूसरा सर्वेक्षण तभी मिलता है जब कोई विश्लेषक इसे मैन्युअल रूप से ट्रिगर करे &mdash; यह किसी अस्थिर टिकट को सर्वे-स्पैम होने से रोकता है।',
            'scale_stars' => 'स्टार',
            'scale_emojis' => 'इमोजी',
            'scale_help' => 'दोनों विकल्प वही 1&ndash;5 नंबर संग्रहीत करते हैं, इसलिए डैशबोर्ड और औसत दोनों ही तरह एक जैसे काम करते हैं &mdash; इससे केवल यह बदलता है कि सर्वेक्षण पेज खुद कैसा दिखता है।',
