            'signin_local' => 'लोकल (उपयोगकर्ता नाम &amp; पासवर्ड)',
            'signin_help' => 'लोकल उपयोगकर्ता पासवर्ड से साइन इन करते हैं। इस विश्लेषक के लिए SSO ज़रूरी बनाने हेतु एक प्रदाता असाइन करें — उनके अगले SSO साइन-इन पर उनकी पहचान अपने आप लिंक हो जाती है (ईमेल से मिलान करके)।',
