        'overview' => [
            'heading' => 'अवलोकन',
            'intro' => 'टिकट मॉड्यूल आपके IT सेवा डेस्क का मूल है। यह सहायता अनुरोधों, घटनाओं और सेवा कार्यों को प्रबंधित करने के लिए एक परिचित ईमेल-क्लाइंट जैसा इंटरफ़ेस देता है। टिकट अंतिम उपयोगकर्ताओं से ईमेल या मैन्युअल रूप से बनाए जाने से आते हैं, और विश्लेषक फ़ोल्डर, प्राथमिकताओं और SLA टाइमर का उपयोग करके उन पर काम करते हैं &mdash; जवाबदेह IT सहायता देने के लिए आपको जो कुछ चाहिए, वह सब यहाँ मौजूद है।',
            'card_inbox_title' => 'इनबॉक्स',
            'card_inbox_body' => 'एक ईमेल क्लाइंट पर आधारित फ़ोल्डर-आधारित इनबॉक्स। My Tickets, Unassigned, All Open और Closed फ़ोल्डर ब्राउज़ करें। पूरा विवरण, इतिहास और कार्रवाइयों वाला रीडिंग पेन खोलने के लिए किसी भी टिकट पर क्लिक करें।',
            'card_dashboard_title' => 'डैशबोर्ड',
            'card_dashboard_body' => 'Chart.js विजेट को अनुकूलित करके अपना निजी डैशबोर्ड बनाएँ। टिकट वॉल्यूम, रिस्पॉन्स टाइम, श्रेणी विभाजन और विश्लेषक वर्कलोड को बार, पाई, डोनट और लाइन चार्ट से देखें।',
            'card_calendar_title' => 'कैलेंडर',
            'card_calendar_body' => 'टिकट को उनकी बनाई गई, नियत या हल की गई तारीख के आधार पर कैलेंडर ग्रिड पर देखें। एक नज़र में टिकट की स्थिति देखकर बकाया आइटम तुरंत पहचानें और अपना सप्ताह योजनाबद्ध करें।',
            'card_rota_title' => 'रोटा',
            'card_rota_body' => 'विश्लेषक शिफ्ट और ऑन-कॉल रोटा शेड्यूल करें। किसी भी समय कौन उपलब्ध है यह देखें, सप्ताहांत और छुट्टियों के लिए कवरेज की योजना बनाएँ, और सुनिश्चित करें कि कोई भी टिकट अनदेखा न रहे।',
        ],
        'inbox' => [
            'heading' => 'इनबॉक्स',
            'intro' => 'इनबॉक्स विश्लेषकों के लिए प्राथमिक कार्यक्षेत्र है। यह तीन-पेन लेआउट का उपयोग करता है &mdash; बाईं ओर फ़ोल्डर, बीच में टिकट सूची, और दाईं ओर रीडिंग पेन &mdash; ताकि आप पेज छोड़े बिना ही ट्राइएज और जवाब दे सकें।',
            'p_folders' => 'फ़ोल्डर पैनल टिकट को तार्किक समूहों में व्यवस्थित करता है। हर फ़ोल्डर एक अपठित गणना दिखाता है ताकि आप नया काम तुरंत पहचान सकें:',
            'field_my' => '<strong>My Tickets</strong> &mdash; वे टिकट जो आपको सौंपे गए हैं। यह आपकी निजी कतार है और हर दिन शुरू करने की सबसे अच्छी जगह है।',
            'field_unassigned' => '<strong>Unassigned</strong> &mdash; वे टिकट जो आ चुके हैं लेकिन जिन्हें अभी तक कोई विश्लेषक नहीं मिला। यहाँ से आइटम चुनकर उनका स्वामित्व लें।',
            'field_all_open' => '<strong>All Open</strong> &mdash; हर वह टिकट जो अभी बंद नहीं हुआ है, चाहे उसका स्वामी कोई भी हो। कुल वॉल्यूम पर नज़र रखने वाले मैनेजरों और टीम लीड के लिए उपयोगी।',
            'field_closed' => '<strong>Closed</strong> &mdash; हल हो चुके टिकट। पिछले समाधान का संदर्भ लेने या किसी समस्या को फिर से खोलने की ज़रूरत होने पर यहाँ खोजें।',
            'field_dept' => '<strong>विभाग फ़ोल्डर</strong> &mdash; विभाग के अनुसार समूहीकृत टिकट (जैसे IT, HR, Finance)। विभाग सेटिंग्स में कॉन्फ़िगर किए जाते हैं और स्वचालित रूप से उप-फ़ोल्डर के रूप में दिखते हैं।',
            'switch_heading' => '<strong>विभाग और विश्लेषक समूहीकरण के बीच स्विच करना</strong>',
            'switch_body' => 'फ़ोल्डर पैनल के ऊपर एक छोटा दो-बटन टॉगल एक ही डेटा के दो दृश्यों के बीच स्विच करता है। <strong>विभाग</strong> समूहीकरण (डिफ़ॉल्ट) हर विभाग के अंतर्गत टिकट सूचीबद्ध करता है, जिसके भीतर स्थिति उप-फ़ोल्डर होते हैं; <strong>विश्लेषक</strong> समूहीकरण इसे पलट देता है ताकि हर शीर्ष-स्तर फ़ोल्डर किसी विश्लेषक की निजी कतार का प्रतिनिधित्व करे, जिसके भीतर स्थिति उप-फ़ोल्डर हों। <strong>Unassigned</strong> फ़ोल्डर हर दृश्य में संदर्भ-अनुसार बदलता है &mdash; विभाग दृश्य में यह उन टिकटों को सूचीबद्ध करता है जिनका कोई विभाग सेट नहीं है; विश्लेषक दृश्य में यह उन टिकटों को सूचीबद्ध करता है जिनका कोई असाइनी नहीं है &mdash; ताकि आप हमेशा देख सकें कि क्या उठाया जाना बाकी है। आपकी पसंद प्रति-विश्लेषक सहेजी जाती है ताकि हर टीम सदस्य सत्रों में अपनी पसंदीदा दृश्य बनाए रखे।',
            'row_name' => 'हर पंक्ति टिकट संदर्भ और फिर एक नाम दिखाती है। डिफ़ॉल्ट रूप से यह <strong>टिकट उठाने वाला व्यक्ति</strong> होता है, और टिकट की पूरी उम्र भर वही बना रहता है। अगर आप इसके बजाय सबसे हाल का संदेश भेजने वाला देखना चाहें — जो आपके जवाब देते ही आपका अपना मेलबॉक्स बन जाता है — तो <strong>Settings &rarr; Row display</strong> के अंतर्गत <strong>Name beside the ticket number</strong> बदलें, जहाँ आप नाम छिपाकर केवल संदर्भ भी छोड़ सकते हैं। वह टैब आपकी अपनी सेटिंग है: यह किसी और के लिए कुछ नहीं बदलती।',
            'tip' => 'सूची में किसी भी टिकट पर क्लिक करके उसे रीडिंग पेन में लोड करें। वहाँ से आप फ़ील्ड अपडेट कर सकते हैं, टिप्पणियाँ जोड़ सकते हैं, ईमेल से जवाब दे सकते हैं, या फ़ाइलें अटैच कर सकते हैं &mdash; यह सब इनबॉक्स से बाहर गए बिना।',
        ],
        'faster' => [
            'heading' => 'तेज़ी से काम करना',
            'intro' => 'चार चीज़ें जो व्यस्त सुबह को संभालने लायक बना देती हैं: सहेजे गए जवाब, एक साथ कई टिकट पर कार्रवाई, और बातचीत को उसकी सही जगह पर रखना।',
            'templates_heading' => 'तैयार जवाब',
            'templates_body' => 'आप बार-बार वही कुछ जवाब भेजते हैं। एक बार लिखें, फिर उसे अपने कर्सर पर डालने के लिए जवाब एडिटर के ऊपर <strong>Templates</strong> पर क्लिक करें &mdash; यह पहले से लिखे गए में जुड़ जाता है, उसकी जगह नहीं लेता। टेम्पलेट रिच टेक्स्ट होते हैं और स्वचालित ईमेल की तरह ही <code>[merge_code]</code> प्लेसहोल्डर सपोर्ट करते हैं, इसलिए इंसर्ट करते ही <code>[requester_first_name]</code> असली नाम बन जाता है।',
            'templates_team' => '<strong>टीम टेम्पलेट</strong> &mdash; सबके साथ साझा, Settings &rarr; Reply templates में सेट किए जाते हैं।',
            'templates_mine' => '<strong>आपके अपने</strong> &mdash; <em>Save draft as template</em> से ड्राफ्ट सहेजें। केवल आपके लिए निजी, किसी अनुमति की ज़रूरत नहीं।',
            'templates_tip' => 'टेम्पलेट का नाम स्थिति के हिसाब से रखें ("Printer offline &mdash; first steps"), उसके शब्दों के हिसाब से नहीं। सुबह 9 बजे आप यही तो ढूँढ़ेंगे।',
            'select_heading' => 'कई टिकट चुनना',
            'select_body' => 'टिकट सूची Outlook या File Explorer जैसे काम करती है। कोई चेकबॉक्स नहीं।',
            'key_click' => 'क्लिक',
            'key_click_d' => 'एक चुनें और उसे खोलें',
            'key_ctrl' => 'Ctrl+क्लिक',
            'key_ctrl_d' => 'एक जोड़ें या हटाएँ, बाकी को वैसा ही छोड़ दें',
            'key_shift' => 'Shift+क्लिक',
            'key_shift_d' => 'आपने आखिरी बार जहाँ क्लिक किया था वहाँ से पूरा ब्लॉक चुनें',
            'key_kb' => 'कीबोर्ड',
            'key_kb_d' => 'चलने के लिए एरो कीज़, बढ़ाने के लिए Shift+एरो, बिखरे हुए टिकट चुनने के लिए Ctrl+एरो और Space, सब कुछ के लिए Ctrl+A, साफ़ करने के लिए Escape',
            'select_actions' => 'कई चुने होने पर, सबके लिए एक साथ स्थिति, प्राथमिकता, विभाग, प्रकार या असाइनी सेट करने के लिए <strong>उनमें से किसी पर भी राइट-क्लिक करें</strong> &mdash; या पूरे सेट को किसी फ़ोल्डर पर खींचें। कई चुने होने पर स्क्रीन क्या दिखाए, यह आपकी पसंद है, अकाउंट मेनू में Preferences के अंतर्गत।',
            'select_tip' => 'अपने चयन में <em>शामिल नहीं</em> किसी टिकट पर राइट-क्लिक करने से चयन साफ़ हो जाता है और केवल उसी एक को लक्षित करता है। यह जान-बूझकर है &mdash; जिस सेट को आप पीछे छोड़ चुके थे, उस पर आप कभी गलती से कार्रवाई नहीं कर सकते।',
            'merge_heading' => 'डुप्लिकेट मर्ज करना',
            'merge_body' => 'दो लोगों ने एक ही आउटेज की रिपोर्ट की? टिकट चुनें, राइट-क्लिक करें, <strong>Merge</strong>। बातचीत एक साथ आ जाती है, और अगर आपने कोई AI प्रोवाइडर कॉन्फ़िगर किया है तो FreeITSM इस बात की एक छोटी ब्रीफिंग लिखता है कि सबने क्या पूछा और अब तक क्या किया जा चुका है, ताकि जो भी इसे उठाए उसे चार थ्रेड पढ़ने न पड़ें।',
            'merge_tip' => 'कुछ भी कभी हटाया नहीं जाता। जिस टिकट को मर्ज कर दिया गया वह अपना संदर्भ बनाए रखता है, खोजा जा सकता है, दिखाता है कि वह कहाँ गया &mdash; और उसी के बारे में पुराने ईमेल का जवाब देने वाला ग्राहक अब भी आप तक पहुँचता है।',
            'split_heading' => 'टिकट विभाजित करना',
            'split_body' => 'इसका उल्टा काम। जब कोई बातचीत के बीच में एक दूसरी, असंबंधित बात उठाता है, तो उस संदेश पर <strong>Split</strong> पर क्लिक करें (या संदेश हेडर पर राइट-क्लिक करें)। यह एक नए टिकट में चला जाता है, और चाहें तो उससे नए हर संदेश को भी साथ ले जा सकता है, और मूल टिकट पर एक मार्कर रह जाता है जो दिखाता है कि वे कहाँ गए।',
            'split_tip' => 'नए टिकट को उचित विषय दें। यह डिफ़ॉल्ट रूप से स्थानांतरित संदेश का विषय लेता है, जो आमतौर पर <em>पुरानी</em> समस्या का "RE:" होता है।',
            'undo_heading' => 'अपना मन बदला',
            'undo_body' => 'दोनों को टिकट पर मौजूद बैनर से पूर्ववत किया जा सकता है। <strong>विभाजन</strong> पूर्ववत करना तब मना कर दिया जाता है जब कोई नए टिकट पर जवाब दे चुका हो, नोट जोड़ चुका हो या समय दर्ज कर चुका हो &mdash; आपको बताया जाता है कि ठीक-ठीक क्या रोक रहा है। <strong>मर्ज</strong> पूर्ववत करने से टिकट को उसके संदेश, नोट और दर्ज किया गया समय वापस मिल जाता है और वह ठीक वैसे ही फिर से खुल जाता है जैसा पहले था, लेकिन मर्ज के बाद दूसरे टिकट पर लिखे गए जवाब वहीं रहते हैं।',
        ],
        'working' => [
            'heading' => 'टिकट के साथ काम करना',
            'intro' => 'हर सहायता अनुरोध एक जीवनचक्र से गुज़रता है: वह बनाया जाता है, ट्राइएज किया जाता है, उस पर काम होता है, और अंततः हल हो जाता है। टिकट मॉड्यूल आपको शुरुआती लॉगिंग से लेकर बंद होने तक हर चरण को कुशलता से प्रबंधित करने के लिए उपकरण देता है।',
            'creating_heading' => '<strong>नया टिकट बनाना</strong>',
            'step1' => '<strong>New पर क्लिक करें</strong> &mdash; इनबॉक्स टूलबार से नया टिकट मॉडल खोलें। अनुरोधकर्ता का नाम और ईमेल पता दर्ज करें ताकि उन्हें अपडेट मिल सकें।',
            'step2' => '<strong>विषय सेट करें</strong> &mdash; समस्या का स्पष्ट, संक्षिप्त सारांश लिखें। यह टिकट सूची में और अंतिम उपयोगकर्ता को भेजी जाने वाली किसी भी ईमेल सूचना में दिखता है।',
            'step3' => '<strong>विभाग, प्रकार और प्राथमिकता चुनें</strong> &mdash; उपयुक्त विभाग, टिकट प्रकार (जैसे Incident, Service Request), और प्राथमिकता स्तर चुनें। ये फ़ील्ड SLA टाइमर और रूटिंग नियमों को चलाते हैं।',
            'step4' => '<strong>विवरण जोड़ें</strong> &mdash; रिच टेक्स्ट एडिटर का उपयोग करके समस्या का पूरा विवरण दें। पुनरुत्पादन के चरण, त्रुटि संदेश, और कोई भी प्रासंगिक जानकारी शामिल करें जो हल करने वाले विश्लेषक को चाहिए होगी।',
            'step5' => '<strong>Save</strong> &mdash; टिकट एक अद्वितीय संदर्भ संख्या के साथ बनाया जाता है और उपयुक्त फ़ोल्डर में दिखता है। प्राथमिकता के आधार पर SLA घड़ी तुरंत शुरू हो जाती है।',
            'editing_heading' => '<strong>टिकट संपादित और प्रबंधित करना</strong>',
            'editing_body' => 'टिकट बनने के बाद, आप रीडिंग पेन से किसी भी फ़ील्ड को अपडेट कर सकते हैं। मुख्य फ़ील्ड में शामिल हैं:',
            'card_status_title' => 'स्थिति',
            'card_status_body' => 'टिकट जीवनचक्र ट्रैक करें: New, Open, In Progress, Pending, Resolved, Closed',
            'card_priority_title' => 'प्राथमिकता',
            'card_priority_body' => 'तात्कालिकता और प्रभाव सेट करें: Critical, High, Medium, Low। हर स्तर का अपना SLA लक्ष्य है',
            'card_category_title' => 'श्रेणी',
            'card_category_body' => 'समस्या के प्रकार को वर्गीकृत करें: Hardware, Software, Network, Access, General। रिपोर्टिंग के लिए उपयोगी',
            'card_analyst_title' => 'असाइन किया गया विश्लेषक',
            'card_analyst_body' => 'टिकट हल करने का ज़िम्मेदार व्यक्ति। पुनः असाइनमेंट गतिविधि ट्रेल में दर्ज किया जाता है',
            'card_enduser_title' => 'अंतिम उपयोगकर्ता',
            'card_enduser_body' => 'अनुरोध करने वाला व्यक्ति। मौजूदा उपयोगकर्ता रिकॉर्ड से जोड़ने के लिए नाम या ईमेल से खोजें',
            'card_dept_title' => 'विभाग',
            'card_dept_body' => 'टिकट को सही टीम तक पहुँचाएँ। विभाग फ़ोल्डर समूहीकरण और डैशबोर्ड फ़िल्टर चलाते हैं',
            'flow_new' => 'New',
            'flow_in_progress' => 'In Progress',
            'flow_resolved' => 'Resolved',
            'flow_closed' => 'Closed',
            'triage_heading' => '<strong>ड्रैग एंड ड्रॉप से ट्राइएज करना</strong>',
            'triage_body' => 'ट्राइएज करने के लिए टिकट खोलना ज़रूरी नहीं है। एक ही गति में फ़ील्ड अपडेट करने के लिए टिकट सूची से किसी भी रो को किसी फ़ोल्डर पर खींचें:',
            'triage_dept' => '<strong>विभाग दृश्य</strong> &mdash; पुनः असाइन करने के लिए किसी विभाग फ़ोल्डर पर छोड़ें, विभाग के अंतर्गत किसी स्थिति उप-फ़ोल्डर पर छोड़कर दोनों को एक साथ अपडेट करें, विभाग साफ़ करने के लिए <strong>Unassigned</strong> पर छोड़ें।',
            'triage_analyst' => '<strong>विश्लेषक दृश्य</strong> &mdash; उस विश्लेषक को स्वामी नियुक्त करने के लिए किसी विश्लेषक के फ़ोल्डर पर छोड़ें (यह <code>assigned_analyst_id</code> और <code>owner_id</code> दोनों सेट करता है ताकि रीडिंग पेन का Owner फ़ील्ड सिंक में रहे), दोनों अपडेट करने के लिए किसी स्थिति उप-फ़ोल्डर पर छोड़ें, असाइनी साफ़ करने के लिए <strong>Unassigned</strong> पर छोड़ें।',
            'triage_spring' => '<strong>स्प्रिंग-लोडेड फ़ोल्डर</strong> &mdash; ड्रैग के दौरान किसी संकुचित फ़ोल्डर पर होवर करें और वह अपने आप विस्तृत हो जाता है (Outlook जैसी शैली) ताकि छोड़ने से पहले ही कोई भी नेस्टेड स्थिति पहुँच योग्य हो।',
            'fullscreen_heading' => '<strong>पूर्ण-स्क्रीन दृश्य</strong>',
            'fullscreen_body' => 'जब आपको किसी एक टिकट पर ध्यान केंद्रित करना हो &mdash; एक लंबी बातचीत, कोई जटिल बदलाव, विस्तृत जवाब लिखना &mdash; पूर्ण-स्क्रीन दृश्य पर स्विच करें। फ़ोल्डर सूची और टिकट सूची गायब हो जाती हैं, बातचीत उपलब्ध चौड़ाई भर लेती है, और गुण (Department, Type, Status, Origin, First Time Fix, IT Training, Owner) दाईं ओर एक वर्टिकल साइडबार में चले जाते हैं।',
            'fullscreen_max' => '<strong>मैक्सिमाइज़ आइकन</strong> &mdash; टिकट विषय पंक्ति के दाएँ छोर पर छोटा आइकन। पूर्ण-स्क्रीन में जाने के लिए क्लिक करें; 3-पेन लेआउट पर लौटने के लिए फिर से क्लिक करें।',
            'fullscreen_dbl' => '<strong>किसी रो पर डबल-क्लिक करें</strong> &mdash; सूची में किसी भी टिकट को सीधे पूर्ण-स्क्रीन में खोलने के लिए उस पर डबल-क्लिक करें, Outlook जैसा "इसे वाकई खोलो" इशारा।',
            'fullscreen_sticks' => '<strong>चयनों के बीच बना रहता है</strong> &mdash; एक बार पूर्ण-स्क्रीन में आने पर, अगले टिकट पर स्विच करना आपको वहीं रखता है। बिना किसी टिकट के चुने पेज को ताज़ा रीलोड करना (F5) डिफ़ॉल्ट 3-कॉलम लेआउट पर लौटा देता है, ताकि आप फ़ोल्डर सूची छिपी होने के साथ फँसे न रह जाएँ।',
            'rightclick_heading' => '<strong>त्वरित कार्रवाइयों के लिए राइट-क्लिक करें</strong>',
            'rightclick_body' => 'सूची में किसी भी टिकट पर राइट-क्लिक करके एक संदर्भ मेनू खोलें। मेनू सबसे ऊपर टिकट संदर्भ दिखाता है ताकि आप जान सकें कि आप किस पर कार्रवाई कर रहे हैं, और हर कार्रवाई राइट-क्लिक किए गए टिकट पर होती है, रीडिंग पेन में अभी जो खुला है उसे <em>बिना</em> बदले &mdash; तब उपयोगी जब आप टिकट A पढ़ रहे हों और टिकट B को अपनी जगह खोए बिना ट्राइएज करना हो।',
            'rightclick_status' => '<strong>Set status &rarr;</strong> &mdash; हर सक्रिय स्थिति को उसके रंग स्वैच के साथ सूचीबद्ध करने वाला फ्लाईआउट सबमेनू। यदि आप उस टिकट पर राइट-क्लिक कर रहे हैं जो आपने खोल रखा है तो मौजूदा मान के आगे एक टिक दिखता है। चुनते ही टिकट अपडेट हो जाता है, एक ऑडिट-ट्रेल प्रविष्टि लिखी जाती है, फ़ोल्डर गणनाएँ रीफ़्रेश होती हैं, और लागू होने पर रीडिंग पेन का Status ड्रॉपडाउन सिंक हो जाता है।',
            'rightclick_priority' => '<strong>Set priority &rarr;</strong> &mdash; वही फ्लाईआउट पैटर्न, सक्रिय प्राथमिकताओं की लुकअप सूची से लिया गया, जिसमें हर एक का रंग स्वैच के रूप में है। पहली पंक्ति असाइनमेंट साफ़ करने के लिए <em>(no priority)</em> विकल्प है (प्राथमिकता nullable है)।',
            'rightclick_assign' => '<strong>Assign to &rarr;</strong> &mdash; हर लोड किए गए विश्लेषक को ग्रे इनिशियल चिप के साथ सूचीबद्ध करने वाला सबमेनू, साथ ही साफ़ करने के लिए ऊपर एक <em>(unassigned)</em> पंक्ति। चुनने पर <code>assigned_analyst_id</code> AND <code>owner_id</code> दोनों सेट होते हैं ताकि रीडिंग पेन का Owner फ़ील्ड सिंक में रहे।',
            'rightclick_cmdb' => '<strong>Link CMDB object&hellip;</strong> &mdash; टाइप करते ही खोजने वाला पिकर खोलता है। लिंक करने के लिए किसी परिणाम पर क्लिक करें, फिर चुनते रहें &mdash; इनपुट साफ़ होकर अगले के लिए फिर से फ़ोकस में आ जाता है, और मॉडल के भीतर एक "Recently linked" लॉग आपके हरे-टिक कन्फर्मेशन की चलती सूची दिखाता है।',
            'rightclick_time' => '<strong>Record time&hellip;</strong> &mdash; मिनट + एक datetime पिकर (डिफ़ॉल्ट रूप से "now", ताकि आप पिछली तारीख भी डाल सकें) + एक वैकल्पिक नोट्स बॉक्स वाला मॉडल खोलता है।',
            'rightclick_tip' => 'यदि जिस टिकट पर आप संदर्भ मेनू से कार्रवाई कर रहे हैं वह संयोग से वही है जो रीडिंग पेन में खुला है, तो वहाँ का संबंधित भाग (Status / Priority ड्रॉपडाउन, CMDB ऑब्जेक्ट, समय प्रविष्टियाँ) मॉडल बंद होते ही अपने आप रीफ़्रेश हो जाता है ताकि UI सिंक में रहे।',
            'time_heading' => '<strong>समय दर्ज करना</strong>',
            'time_body' => 'किसी टिकट पर लगा समय रीडिंग पेन में एक समर्पित <strong>Time Entries</strong> सेक्शन में दर्ज होता है, जो लिंक किए गए CMDB ऑब्जेक्ट पैनल और Notes पैनल के बीच बैठता है। हेडर चलता हुआ कुल दिखाता है (जैसे "Total 2h 30m"), और नीचे हर प्रविष्टि लगा समय, विश्लेषक, तारीख, और आपके जोड़े गए किसी भी नोट को दिखाती है।',
            'time_step1' => '<strong>इनलाइन फॉर्म</strong> &mdash; न्यूमेरिक इनपुट में लगे मिनट टाइप करें, नोट्स इनपुट में एक वैकल्पिक संक्षिप्त विवरण, और <strong>Add</strong> पर क्लिक करें। नई प्रविष्टि आपके नाम और वर्तमान टाइमस्टैम्प के साथ तुरंत सूची में सबसे ऊपर दिखती है।',
            'time_step2' => '<strong>राइट-क्लिक से पिछली तारीख डालना</strong> &mdash; यदि आपको पहले दर्ज करना भूला गया समय दर्ज करना है, तो सूची में टिकट पर राइट-क्लिक करें और <strong>Record time&hellip;</strong> चुनें। मॉडल में एक datetime पिकर शामिल है ताकि आप प्रविष्टि पर काम होने के असली समय की मुहर लगा सकें।',
            'time_step3' => '<strong>अपनी ही प्रविष्टियाँ हटाना</strong> &mdash; आपके दर्ज की गई प्रविष्टियों के बगल में एक छोटा &times; बटन दिखता है। इसे क्लिक करें (और पुष्टि करें) तो सॉफ्ट-डिलीट हो जाता है &mdash; रो ऑडिट के लिए डेटाबेस में <code>is_active = 0</code> के साथ बनी रहती है, लेकिन सूची से गायब हो जाती है। आप दूसरे विश्लेषकों की प्रविष्टियाँ नहीं हटा सकते।',
            'time_tip1' => 'समय को सादे मिनट के रूप में संग्रहीत किया जाता है (45 min, 90 min, आदि) और UI में <code>45m</code> या <code>1h 30m</code> के रूप में दिखाया जाता है &mdash; छोटी फिक्स के लिए काफ़ी बारीक, दशमलव-घंटे की गोलाई की झंझट के बिना।',
            'time_tip2' => 'हर फ़ील्ड बदलाव टिकट के गतिविधि ट्रेल में दर्ज होता है। आप हमेशा देख सकते हैं कि किसने क्या और कब बदला, जो ऑडिट अनुपालन और विश्लेषकों के बीच हैंडओवर के लिए ज़रूरी है।',
        ],
        'comments' => [
            'heading' => 'टिप्पणियाँ &amp; अनुलग्नक',
            'intro' => 'गतिविधि ट्रेल हर टिकट का मूल है। यह हर की गई कार्रवाई को कैद करता है &mdash; टिप्पणियाँ, फ़ील्ड बदलाव, भेजी गई ईमेल, और अटैच की गई फ़ाइलें &mdash; एक कालानुक्रमिक टाइमलाइन में जो सहायता अनुरोध की पूरी कहानी बताती है।',
            'adding_heading' => '<strong>टिप्पणियाँ जोड़ना</strong>',
            'step1' => '<strong>टिकट खोलें</strong> &mdash; उसका रीडिंग पेन लोड करने के लिए इनबॉक्स में किसी भी टिकट पर क्लिक करें। पूरा गतिविधि ट्रेल और नीचे टिप्पणी बॉक्स देखने के लिए नीचे स्क्रॉल करें।',
            'step2' => '<strong>अपना नोट लिखें</strong> &mdash; टिप्पणी एडिटर खोलने के लिए Add Note बटन का उपयोग करें। नोट डिफ़ॉल्ट रूप से आंतरिक होते हैं, केवल सेवा डेस्क के विश्लेषकों को दिखते हैं।',
            'step3' => '<strong>ईमेल से जवाब दें या अग्रेषित करें</strong> &mdash; अंतिम उपयोगकर्ता या किसी तीसरे पक्ष को संदेश भेजने के लिए Reply या Forward कार्रवाइयों का उपयोग करें। ईमेल आउटबाउंड संदेश सामग्री के साथ गतिविधि ट्रेल में दर्ज होती है।',
            'files_heading' => '<strong>फ़ाइल अनुलग्नक</strong>',
            'files_body' => 'स्क्रीनशॉट, लॉग, दस्तावेज़, या कोई भी सहायक फ़ाइल सीधे टिकट से अटैच करें। फ़ाइलों को अनुलग्नक ड्रॉप ज़ोन में खींचा जा सकता है या फ़ाइल ब्राउज़र से चुना जा सकता है। अनुलग्नक सर्वर पर संग्रहीत होते हैं और टिकट के गतिविधि ट्रेल से जुड़े रहते हैं ताकि कुछ भी खो न जाए।',
            'audit_heading' => '<strong>ऑडिट लॉगिंग</strong>',
            'audit_body' => 'गतिविधि ट्रेल बिना विश्लेषक के हस्तक्षेप के हर कार्रवाई को स्वचालित रूप से दर्ज करता है। जब प्राथमिकता Medium से High में बदली जाती है, तो पुराना और नया मान दोनों कैद होते हैं। जब कोई टिकट पुनः असाइन होता है, तो पिछला और नया दोनों विश्लेषक दर्ज होते हैं। यह एक पूर्ण, छेड़छाड़-रहित इतिहास बनाता है जो ITIL ऑडिट आवश्यकताओं को पूरा करता है और मैनेजरों को यह समझने में मदद करता है कि टिकट कैसे संभाले जा रहे हैं।',
            'tip' => 'ईमेल से जवाब देते समय, आप उसी कार्रवाई में Cc प्राप्तकर्ता जोड़ सकते हैं और फ़ाइलें अटैच कर सकते हैं। पूरी ईमेल बातचीत टिकट के गतिविधि ट्रेल में थ्रेड हो जाती है, जिससे सारा संचार एक ही जगह रहता है।',
        ],
        'ai' => [
            'heading' => 'AI टूल',
            'intro' => 'टिकट वर्कफ़्लो के भीतर दो Claude-संचालित फ़ीचर मौजूद हैं: <strong>Reply Cleanup</strong> एक कच्चे ड्राफ्ट को ठीक से फ़ॉर्मेट की गई ईमेल में फिर से लिखता है, और <strong>Ask AI</strong> टिकट संदर्भ का उपयोग करके प्राकृतिक भाषा में नॉलेज बेस खोजता है।',
            'cleanup_heading' => '<strong>Reply Cleanup &mdash; जवाब एडिटर में ✨ बटन</strong>',
            'cleanup_body' => 'जवाब में एक जल्दी का कच्चा ड्राफ्ट टाइप करें (या सिर्फ़ बुलेट पॉइंट जैसे *"need to restart the print service, take screenshot for them"*) और <strong>✨ Cleanup</strong> बटन पर क्लिक करें। Claude इसे ठीक से फ़ॉर्मेट की गई ईमेल के रूप में फिर से लिखता है &mdash; अनुरोधकर्ता की ओर से <em>Dear [name],</em> अभिवादन जोड़ता है, व्याकरण ठीक करता है, कॉन्फ़िगर किया गया टोन लागू करता है, और <em>Kind regards,</em> के साथ समाप्त करता है। प्रॉम्प्ट को इस तरह लॉक किया गया है कि यह तकनीकी विवरण नहीं गढ़ेगा, माफ़ी नहीं बनाएगा, या आपके लिखे से ज़्यादा कुछ नहीं जोड़ेगा।',
            'cleanup_streams' => '<strong>लाइव स्ट्रीम होता है</strong> &mdash; जैसे-जैसे Claude जनरेट करता है, फिर से लिखा गया संस्करण एडिटर में दिखता जाता है (स्पिनर के आगे इंतज़ार नहीं करना पड़ता)।',
            'cleanup_undo' => '<strong>30 सेकंड के लिए Undo लिंक</strong> &mdash; अगर Claude रिराइट बिगाड़ दे, तो रिराइट पूरा होने के बाद 30 सेकंड के लिए एडिटर के नीचे एक छोटा <em>Undo</em> लिंक दिखता है, जो मूल ड्राफ्ट वापस ले आता है।',
            'cleanup_tone' => '<strong>टोन के अनुसार</strong> &mdash; <strong>Settings &rarr; Reply Cleanup</strong> के अंतर्गत तीन टोन प्रीसेट कॉन्फ़िगर किए जा सकते हैं: <em>Friendly</em> (डिफ़ॉल्ट), <em>Formal</em>, <em>Brief</em>। जो आपकी टीम की शैली से मेल खाए वह चुनें।',
            'cleanup_key' => '<strong>अपनी खुद की API key</strong> &mdash; RFP / Knowledge / Workflow AI फ़ीचर से अलग Anthropic key, ताकि इसका उपयोग Anthropic बिलिंग डैशबोर्ड पर अपनी खुद की लाइन के रूप में दिखे। <strong>Settings &rarr; Reply Cleanup</strong> के अंतर्गत कॉन्फ़िगर किया जाता है।',
            'cleanup_tip' => 'Cleanup सामान्य "मैंने यह कोशिश की, कृपया X आज़माएँ" जैसे जवाबों के लिए सबसे उपयोगी है। लंबे, बारीक संदेशों के लिए आप उन्हें खुद लिखना चाहेंगे &mdash; AI संरचना में अच्छा है लेकिन आपके विशिष्ट माहौल को नहीं जानता।',
            'ask_heading' => '<strong>Ask AI &mdash; टिकट टूलबार में 🤖 बटन</strong>',
            'ask_body' => 'खुले टिकट के विषय, बॉडी और रीडिंग-पेन संदर्भ को जानने वाला स्लाइड-इन चैट पैनल खोलने के लिए टिकट टूलबार में <strong>Ask AI</strong> बटन (🤖) पर क्लिक करें। इससे *"have we seen this before?"* या *"what\'s the usual fix for this error?"* जैसे प्रश्न पूछें और यह Claude + OpenAI embeddings के ज़रिए <a href="../knowledge/" style="color:#0078d4;">Knowledge</a> बेस को अर्थ के आधार पर खोजता है और प्रासंगिक लेख, उन्हें खोलने के सीधे लिंक के साथ, जवाब में देता है।',
            'ask_context' => '<strong>संदर्भ-जागरूक</strong> &mdash; पैनल जानता है कि आप कौन सा टिकट देख रहे हैं, इसलिए आप सामान्य प्रश्न पूछ सकते हैं और यह खुद प्रासंगिक संदर्भ समझ लेता है।',
            'ask_linked' => '<strong>लिंक किए गए लेख</strong> &mdash; सुझाव क्लिक करने योग्य होते हैं और मिलान करने वाला नॉलेज लेख एक नए टैब में खोलते हैं।',
            'ask_shared' => '<strong>Knowledge मॉड्यूल के साथ साझा</strong> &mdash; AI, Knowledge AI खोज जैसी ही key + मॉडल उपयोग करता है, इसलिए एक बार कॉन्फ़िगर करने से दोनों मिल जाते हैं। सेटअप विवरण के लिए Knowledge मॉड्यूल की सहायता देखें।',
        ],
        'csat' => [
            'heading' => 'ग्राहक संतुष्टि सर्वेक्षण (CSAT)',
            'intro' => 'टिकट हल होने पर अनुरोधकर्ता को 1&ndash;5 का संतुष्टि सर्वेक्षण ईमेल करें, बिना-लॉगिन लैंडिंग पेज पर जवाब कैद करें, और प्रति-विश्लेषक रुझान एक समर्पित एनालिटिक्स पेज पर ट्रैक करें।',
            'modes_heading' => '<strong>दो ट्रिगर मोड &mdash; एक चुनें</strong>',
            'mode_auto' => '<strong>Auto on close</strong> &mdash; टिकट किसी भी बंद स्थिति में जाते ही सर्वेक्षण अपने आप कतार में लग जाता है। विश्लेषक को कुछ करने की ज़रूरत नहीं &mdash; समाधान ही सर्वेक्षण चलाता है।',
            'mode_manual' => '<strong>Manual only</strong> &mdash; जब पूछना हो तो विश्लेषक टिकट टूलबार में ⭐ <strong>Feedback</strong> बटन क्लिक करता है। जब आप टिकट-दर-टिकट तय करना चाहें कि फ़ीडबैक माँगना है या नहीं, तब उपयोगी।',
            'mode_off' => '<strong>Off</strong> &mdash; फ़ीचर बंद; कोई सर्वेक्षण ईमेल नहीं भेजी जाती।',
            'modes_choose' => '<strong>Tickets &rarr; Settings &rarr; CSAT</strong> के अंतर्गत चुनें। <em>auto</em> मोड में भी मैनुअल बटन काम करता है &mdash; ज़रूरत पड़ने पर विश्लेषक ऐसे टिकट पर भी फिर से फ़ीडबैक माँग सकते हैं जिसका सर्वेक्षण पहले ही हो चुका है।',
            'template_heading' => '<strong>ईमेल टेम्पलेट</strong>',
            'template_body' => 'सर्वेक्षण ईमेल की सामग्री मौजूदा <strong>Email templates</strong> टैब से आती है &mdash; इवेंट <strong>CSAT survey</strong> (<em>Ticket assigned</em> / <em>Ticket closed</em> के साथ नया इवेंट) वाला एक टेम्पलेट बनाएँ और जहाँ भी रेटिंग URL दिखाना हो वहाँ <code>[csat_link]</code> मर्ज कोड जोड़ें। मानक मर्ज कोड (<code>[requester_name]</code>, <code>[ticket_reference]</code>, <code>[analyst_name]</code>) सामान्य रूप से उपलब्ध हैं।',
            'template_tip' => 'अगर कोई सक्रिय CSAT टेम्पलेट मौजूद नहीं है, तो <em>Feedback</em> बटन एक स्पष्ट त्रुटि के साथ मना कर देता है और ऑटो-ट्रिगर चुपचाप छूट जाता है &mdash; आप कभी भी मृत सर्वेक्षण लिंक नहीं बना सकते।',
            'survey_heading' => '<strong>सर्वेक्षण पेज</strong>',
            'survey_body' => 'अनुरोधकर्ता ईमेल में लिंक क्लिक करता है और एक बिना-लॉगिन पेज पर पहुँचता है जिसमें 1&ndash;5 पिकर और एक वैकल्पिक टिप्पणी बॉक्स होता है। <strong>Settings &rarr; CSAT</strong> के अंतर्गत दो विज़ुअल शैलियाँ कॉन्फ़िगर की जा सकती हैं:',
            'survey_stars' => '<strong>Stars</strong> &mdash; क्लासिक फिल-ऑन-होवर ट्रेलिंग व्यवहार। स्टार #3 पर होवर करने से #1+#2+#3 सुनहरे रंग में भर जाते हैं। लॉक करने के लिए क्लिक करें।',
            'survey_emojis' => '<strong>Emojis</strong> &mdash; 5 चेहरे 😡 🙁 😐 🙂 😀 40% ओपैसिटी पर ग्रेस्केल में शुरू होते हैं; होवर किया गया या चुना गया चेहरा 1.25&times; स्केल पर पूरे रंग में लौट आता है। लॉक करने के लिए क्लिक करें।',
            'survey_store' => 'दोनों मोड एक ही 1&ndash;5 संख्या संग्रहीत करते हैं ताकि किसी भी शैली में डैशबोर्ड और औसत समान रूप से काम करें। सर्वेक्षण URL वन-शॉट है &mdash; एक बार उपयोगकर्ता सबमिट कर दे, तो वही लिंक फिर से सबमिशन से मना कर देता है।',
            'analytics_heading' => '<strong>एनालिटिक्स पेज</strong>',
            'analytics_body' => '<code>tickets/csat/</code> पर एनालिटिक्स डैशबोर्ड खोलने के लिए ⭐ <strong>CSAT</strong> नैव बटन (Rota और Settings के बीच) पर क्लिक करें। विंडो चुनने योग्य: 7 / 30 / 90 / 365 दिन।',
            'card_kpi_title' => 'KPI टाइल',
            'card_kpi_body' => 'औसत रेटिंग (5 में से), जवाब की संख्या, जवाब दर (जवाब दिए ÷ भेजे गए)',
            'card_dist_title' => 'स्कोर वितरण',
            'card_dist_body' => 'सटीक गणना और प्रतिशत दिखाने वाला 1–5 रेटिंग का बार चार्ट',
            'card_leader_title' => 'प्रति-विश्लेषक लीडरबोर्ड',
            'card_leader_body' => 'प्रति विश्लेषक औसत रेटिंग + जवाब की संख्या, avg desc के क्रम में। विकास संबंधी बातचीत के लिए उपयोग करें',
            'card_recent_title' => 'हाल की प्रतिक्रियाएँ',
            'card_recent_body' => 'मुफ़्त-टेक्स्ट टिप्पणियों सहित 25 सबसे हाल की रेटिंग, स्रोत टिकट से वापस लिंक की गई',
            'analytics_tip' => 'प्रति-विश्लेषक श्रेय टिकट के पुनः असाइनमेंट के बाद भी बना रहता है क्योंकि विश्लेषक id भेजने के समय सर्वेक्षण रो पर कैद कर ली जाती है, लाइव लुकअप से नहीं। यदि बंद होने से पहले टिकट कई हाथों से गुज़रा हो, तो जिस विश्लेषक ने उसे वाकई बंद किया वही रेटिंग का मालिक है।',
            'one_heading' => '<strong>प्रति टिकट एक सर्वेक्षण</strong>',
            'one_body' => 'यदि <em>One survey per ticket</em> चालू है (डिफ़ॉल्ट), तो फिर से खुलने और फिर बंद होने वाले टिकट को दूसरा सर्वेक्षण तभी मिलता है जब कोई विश्लेषक इसे मैन्युअल रूप से ट्रिगर करे &mdash; इससे बार-बार चक्कर लगाने वाले किसी अस्थिर टिकट पर सर्वेक्षण-स्पैम रुक जाता है। यदि हर बंद होने पर एक नया सर्वेक्षण चाहिए तो इसे बंद कर दें।',
        ],
        'users' => [
            'heading' => 'उपयोगकर्ता प्रबंधन',
            'intro' => '<strong>Users</strong> नैव बटन <code>tickets/users.php</code> खोलता है &mdash; हर अंतिम उपयोगकर्ता (जो टिकट उठाते हैं, विश्लेषक नहीं) की डायरेक्टरी, हर एक के टिकट इतिहास के साथ।',
            'p_intro' => 'उपयोगकर्ता चार सक्रिय तरीकों से सिस्टम में आते हैं &mdash; पोर्टल स्व-पंजीकरण, किसी नए प्रेषक से आने वाली ईमेल, मेलबॉक्स पोलर, या ट्रिगर किए गए टिकट से एक बनाने वाला वर्कफ़्लो इंजन। यह ज़्यादातर मामलों को कवर करता है, लेकिन Users पेज आपको <strong>पहले से बनाने</strong> (जैसे कोई नया कर्मचारी जिसे जल्द ही एक्सेस चाहिए होगा) और मौजूदा रो को <strong>संपादित</strong> या <strong>हटाने</strong> भी देता है।',
            'add_heading' => '<strong>उपयोगकर्ता जोड़ें</strong>',
            'add_body' => 'उपयोगकर्ता-सूची हेडर में <strong>Add</strong> बटन एक मॉडल खोलता है:',
            'add_email' => '<strong>ईमेल</strong> (आवश्यक) &mdash; अद्वितीय होना चाहिए, और किसी विश्लेषक अकाउंट से टकराना नहीं चाहिए।',
            'add_names' => '<strong>प्रदर्शन नाम / पसंदीदा नाम</strong> &mdash; वैकल्पिक। पसंदीदा नाम वह है जिससे उपयोगकर्ता ईमेल में खुद को संबोधित होते देखना चाहता है (जैसे <em>"Ed Mozley"</em> की जगह <em>"Ed"</em>)।',
            'add_password' => '<strong>पासवर्ड</strong> &mdash; वैकल्पिक। इसे खाली छोड़ने से एक <em>पासवर्ड-रहित</em> अकाउंट बनता है &mdash; बिल्कुल वही स्थिति जिसमें इनबाउंड-टिकट उपयोगकर्ता शुरू होते हैं। उपयोगकर्ता बाद में सेल्फ-सर्विस पोर्टल के register फ़्लो से अपना पासवर्ड सेट करके अकाउंट क्लेम कर सकता है।',
            'add_details' => '<strong>पद, विभाग, कार्यालय, फ़ोन, मोबाइल, कर्मचारी ID और मैनेजर</strong> &mdash; सभी वैकल्पिक, और सभी लॉगिन की बजाय <em>व्यक्ति</em> का वर्णन करते हैं। भरने लायक: <strong>कार्यालय</strong> बताता है कि कोई किस साइट पर है इससे पहले कि आप उसे ढूँढ़ने निकलें, <strong>मैनेजर</strong> रिपोर्टिंग लाइन दर्ज करता है, और <strong>कर्मचारी ID</strong> वह जॉइन-की है जब आप किसी पेरोल सिस्टम से मिलान करते हैं जिसने कभी ईमेल पते के बारे में नहीं सुना। जहाँ आप किसी डायरेक्टरी से इम्पोर्ट करते हैं, ये सभी पहले से भरे आते हैं। एक CardDAV एड्रेस बुक कर्मचारी ID और मैनेजर को छोड़कर बाकी सब भर देती है, क्योंकि एक कॉन्टैक्ट कार्ड में इन्हें रखने की कोई जगह नहीं होती।',
            'managed_heading' => '<strong>कहीं और प्रबंधित होने वाले लोग</strong>',
            'source_body' => '<strong>कोई व्यक्ति कहाँ से आता है</strong>, यह उसके विवरण में नाम से बताया जाता है (<em>Details from: Contoso AD - directory</em>), और खोज बॉक्स के नीचे <strong>Source</strong> फ़िल्टर केवल किसी एक डायरेक्टरी या address book के लोगों को, या केवल FreeITSM में जोड़े गए लोगों को सूचीबद्ध करता है, हर एक के बगल में एक गिनती के साथ। यह तब दिखाई देता है जब कोई किसी स्रोत से जुड़ जाता है।',
            'add_book_body' => '<strong>Add to address book.</strong> जिसने ईमेल किया वह यहाँ मौजूद है लेकिन किसी address book में नहीं। अगर किसी व्यवस्थापक ने <em>Let analysts add people to this address book</em> (System &rarr; Authentication, address book पर) चालू कर रखा है, तो उस व्यक्ति के पास Edit के बगल में एक <strong>Add to address book</strong> बटन आ जाता है। यह पहले पूछता है, यह दिखाते हुए कि कार्ड पर क्या जाएगा, फिर उनका contact बनाता है और उन्हें लिंक कर देता है — वही व्यक्ति, कोई कॉपी नहीं। यह किसी ऐसे व्यक्ति को नहीं जोड़ेगा जिसका ईमेल पता उस book में पहले से है (इसके बजाय import चलाएँ), और यह सुनिश्चित करता है कि अगला import नए contact को उठा ले, वरना कार्ड को वापस निकाल देता है।',
            'managed_body' => 'जहाँ किसी व्यक्ति को इम्पोर्ट किया गया हो &mdash; LDAP या Active Directory से, या किसी CardDAV एड्रेस बुक से &mdash; वही विवरण <strong>केवल-पढ़ने-योग्य</strong> होते हैं और मॉडल यह बता देता है। वे जहाँ से आए हैं वही उनके लिए सत्य का स्रोत है, और अगला इम्पोर्ट यहाँ टाइप किए गए किसी भी बदलाव को अधिलेखित कर देगा &mdash; इसलिए सेव को सीधे मना कर दिया जाता है, न कि स्वीकार करके एक घंटे बाद चुपचाप पलट दिया जाता है। बदलाव स्रोत पर करें; रिकॉर्ड पर बाकी सब, कंपनी और पासवर्ड सहित, संपादन-योग्य रहता है।',
            'edit_heading' => '<strong>उपयोगकर्ता संपादित करें</strong>',
            'edit_body' => 'सूची से एक उपयोगकर्ता चुनें, फिर विवरण हेडर में <strong>Edit</strong> क्लिक करें। वही मॉडल, पहले से भरा हुआ। बिना पासवर्ड के सहेजने से मौजूदा हैश अछूता रहता है; एक देने से वह रीसेट हो जाता है।',
            'delete_heading' => '<strong>उपयोगकर्ता हटाएँ</strong>',
            'delete_body' => '<strong>Delete</strong> बटन <strong>FK-safe</strong> है: यह मना कर देता है अगर उपयोगकर्ता किसी टिकट पर अनुरोधकर्ता है या <code>users_assets</code> में इसकी कोई रो है, और स्पष्ट संदेश देता है <em>"Cannot delete: this user is the requester on N ticket(s). Reassign or close those tickets first."</em>। ऑडिट इतिहास कभी चुपचाप नहीं टूट सकता।',
            'tip' => 'सभी मॉडल फ़ील्ड में ब्राउज़र ऑटोफ़िल बंद है (पासवर्ड फ़ील्ड पर <code>autocomplete="new-password"</code> सहित) ताकि विश्लेषक के अपने सहेजे गए क्रेडेंशियल किसी ऐसे फ़ॉर्म में न सुझाए जाएँ जिसका पूरा मकसद <em>किसी और</em> का रिकॉर्ड बनाना है।',
            'groups_heading' => '<strong>समूह</strong>',
            'groups_body' => '<strong>People</strong> के बगल में <strong>Groups</strong> टैब लोगों के नामित समूह रखता है &mdash; विश्लेषक और सेल्फ-सर्विस पोर्टल उपयोगकर्ता एक ही समूह में साथ। एक समूह यहाँ एक बार बनाया जाता है और फिर पूरे FreeITSM में उपयोग होता है, ताकि आपको एक ही सूची दो बार बनाए बिना उसे किसी नॉलेज फ़ोल्डर तक पहुँच दे सकें या उसे कोई ट्रेनिंग कोर्स असाइन कर सकें।',
            'groups_make' => '<strong>एक बनाएँ</strong> Groups टैब पर <strong>Add</strong> से: एक नाम, और भरने लायक एक विवरण, क्योंकि अगले व्यक्ति को यह पता चलना चाहिए कि समूह किसलिए है।',
            'groups_add' => '<strong>लोग जोड़ें</strong> उन्हें खोजकर &mdash; यह विश्लेषक और पोर्टल उपयोगकर्ता दोनों को एक साथ ढूँढ़ लेता है, इसलिए आपको यह जानने की ज़रूरत नहीं कि कोई किस तरह का है।',
            'groups_expiry' => 'जहाँ एक्सेस अस्थायी हो वहाँ <strong>सदस्यता को एक अंतिम तारीख दें</strong>। दो हफ़्ते के लिए साइट पर आए तीन इंजीनियर एक आखिरी दिन के साथ शामिल होते हैं और वह तारीख आते ही अपने आप समूह से बाहर हो जाते हैं। एक समाप्त सदस्यता सूची में बनी रहती है, समाप्त के रूप में चिह्नित, ताकि आप अब भी देख सकें कि किसकी एक्सेस थी और कब तक।',
            'groups_uses' => '<strong>समूह किस काम आता है:</strong> किसी नॉलेज फ़ोल्डर तक एक्सेस देना, और एक साथ कई लोगों को LMS ट्रेनिंग असाइन करना। सदस्यता में बदलाव तुरंत लागू होते हैं &mdash; बाद में फिर से लागू करने के लिए कुछ नहीं बचता।',
            'groups_admin' => '<strong>Tickets मॉड्यूल वाला कोई भी समूह देख सकता है; केवल एक प्रशासक ही किसी को बदल सकता है।</strong> किसी को समूह में जोड़ने से उसे किसी प्रतिबंधित नॉलेज फ़ोल्डर तक एक्सेस भी मिल सकती है, इसलिए यह फ़ाइलिंग का एक टुकड़ा नहीं बल्कि एक्सेस का अनुदान है।',
        ],
        'dash' => [
            'heading' => 'डैशबोर्ड',
            'intro' => 'टिकट डैशबोर्ड अनुकूलन योग्य Chart.js विजेट के साथ एक नज़र में एनालिटिक्स देता है। हर विश्लेषक का अपना डैशबोर्ड लेआउट है, ताकि आप उन मेट्रिक्स पर ध्यान दे सकें जो आपकी भूमिका के लिए मायने रखते हैं &mdash; चाहे वह निजी वर्कलोड हो, टीम की उत्पादकता, या SLA अनुपालन।',
            'step1' => '<strong>Library खोलें</strong> &mdash; एडिटिंग मोड में जाने के लिए Edit Dashboard क्लिक करें, फिर विजेट लाइब्रेरी ब्राउज़ करें। पहले से बने विजेट में से चुनें या चार्ट प्रकार और एग्रीगेट करने के लिए डेटा प्रॉपर्टी चुनकर अपना खुद बनाएँ।',
            'step2' => '<strong>विजेट जोड़ें</strong> &mdash; लाइब्रेरी में किसी भी विजेट पर + बटन क्लिक करके उसे अपने डैशबोर्ड में जोड़ें। यह तुरंत दिखता है और आपके टिकट डेटाबेस से लाइव डेटा दिखाना शुरू कर देता है।',
            'step3' => '<strong>कॉन्फ़िगर करें</strong> &mdash; किसी भी विजेट के शीर्षक, चार्ट प्रकार (bar, pie, doughnut, line, stacked bar, multi-line), दिनांक सीमा फ़िल्टर, विभाग फ़िल्टर, और समय समूहीकरण (daily, weekly, monthly) को अनुकूलित करने के लिए कॉग आइकन क्लिक करें।',
            'step4' => '<strong>व्यवस्थित करें</strong> &mdash; विजेट को फिर से क्रमबद्ध करने के लिए उन्हें खींचें और छोड़ें। आपका लेआउट प्रति-विश्लेषक सहेजा जाता है ताकि यह सत्रों में बना रहे।',
            'examples' => 'सामान्य विजेट उदाहरणों में शामिल हैं: <strong>Tickets by Status</strong> (open बनाम resolved बनाम closed दिखाने वाला doughnut चार्ट), <strong>Tickets by Priority</strong> (गंभीरता के अनुसार वॉल्यूम का bar चार्ट), <strong>Weekly Volume</strong> (समय के साथ नए टिकट ट्रैक करने वाला line चार्ट), और <strong>Analyst Workload</strong> (हर विश्लेषक के सक्रिय टिकट दिखाने वाला stacked bar)।',
            'tip' => 'व्यक्तिगत विजेट पर दिनांक सीमा फ़िल्टर का उपयोग करके वर्तमान प्रदर्शन की पिछली अवधियों से तुलना करें। उदाहरण के लिए, एक "This Month vs Last Month" दृश्य टिकट वॉल्यूम में रुझान जल्दी पहचानने में मदद करता है।',
        ],
        'cal_rota' => [
            'heading' => 'कैलेंडर &amp; रोटा',
            'intro' => 'दो शेड्यूलिंग टूल आपकी टीम को व्यवस्थित रखने में मदद करते हैं: समय के साथ वर्कलोड को विज़ुअलाइज़ करने वाला एक टिकट कैलेंडर, और शिफ्ट व ऑन-कॉल उपलब्धता प्रबंधित करने के लिए एक स्टाफ़ रोटा।',
            'cal_heading' => '<strong>कैलेंडर दृश्य</strong>',
            'cal_body' => 'कैलेंडर हर उस टिकट को प्लॉट करता है जिसे आपने शेड्यूल किया है &mdash; <strong>Schedule work</strong> के ज़रिए, जो टिकट पर और इनबॉक्स के राइट-क्लिक मेनू पर मौजूद है &mdash; उसके शेड्यूल किए गए समय पर एक रंगीन ब्लॉक के रूप में, एक निश्चित घंटे की बजाय उसकी <strong>असली लंबाई</strong> पर बना। लाल ब्लॉक <em>High</em> प्राथमिकता हैं, हरे <em>Low</em>, नीला बाकी सब कुछ। नेविगेट करने के लिए <em>Today</em>, <em>&lt;</em> / <em>&gt;</em> शेवरॉन, और <strong>Month / Week / Day</strong> टॉगल का उपयोग करें।',
            'cal_scope' => '<strong>Mine या Everyone।</strong> कैलेंडर आपके अपने शेड्यूल किए गए काम पर खुलता है, दृश्य बटन के बगल में एक <strong>Everyone</strong> स्विच के साथ; आपकी पसंद याद रखी जाती है। Everyone में हर टिकट पर <strong>उसके स्वामी के लिए एक रंग</strong> होता है, स्क्रीन पर वाकई मौजूद लोगों के नाम वाली एक लेजेंड के साथ, और किसी टिकट पर होवर करने पर बिना देखे ही पता चल जाता है कि वह किसका है। किसी से कुछ छिपाया नहीं जाता &mdash; ये वही टिकट हैं जो इनबॉक्स पहले से सूचीबद्ध करता है।',
            'cal_edit' => '<strong>काम को फिर से व्यवस्थित करना।</strong> <strong>किसी टिकट को खींचें</strong> किसी दूसरे दिन या समय पर: Month दृश्य में यह अपना समय बनाए रखता है, और Week व Day दृश्य में यह उस समय को अपना लेता है जहाँ आप उसे छोड़ते हैं, निकटतम चौथाई घंटे पर स्नैप किया हुआ। इसकी लंबाई कभी नहीं बदलती &mdash; खींचना कहता है <em>इसे तब शुरू करो</em>, <em>इसे लंबा बना दो</em> नहीं। या <strong>किसी टिकट पर क्लिक करें</strong> उसे खोलने के लिए, जहाँ आप तारीख, समय, अवधि और all-day सेटिंग बदल सकते हैं, या शेड्यूल पूरी तरह साफ़ कर सकते हैं। कैलेंडर हर कुछ सेकंड में <strong>खुद को रीफ़्रेश</strong> भी करता है, ताकि कोई सहकर्मी कुछ शेड्यूल करे तो वह आपके रीलोड किए बिना दिख जाए &mdash; और जब आपने कोई टिकट खोल रखा हो या ड्रैग के बीच में हों तो यह रुक जाता है।',
            'cal_month' => '<strong>Month दृश्य</strong> &mdash; एक हफ़्ते के हेडर स्ट्रिप के साथ क्लासिक 6-रो ग्रिड; हर दिन का सेल अपने शुरुआती समय के साथ तीन टिकट पिल तक दिखाता है, साथ ही एक <em>+N more</em> लिंक जो उस तारीख के लिए Day दृश्य में ले जाता है। आज का दिन हाइलाइट किया जाता है।',
            'cal_week' => '<strong>Week दृश्य</strong> &mdash; ऊपर Mon&ndash;Sun, 24 घंटे की वर्टिकल टाइमलाइन पर। टिकट अपने शेड्यूल किए गए समय पर रेंडर होते हैं, इसलिए 15 मिनट का काम और दोपहर भर चलने वाला रीबिल्ड अलग दिखते हैं। एक all-day टिकट पूरे कॉलम को घेरने की बजाय अपने दिन के ऊपर एक पतली पट्टी के रूप में बैठता है। आज का कॉलम हाइलाइट किया जाता है; हफ़्ते का हेडर टिका रहता है जबकि घंटे का ग्रिड स्क्रॉल होता है।',
            'cal_day' => '<strong>Day दृश्य</strong> &mdash; चुने गए दिन के लिए वही 24-घंटे की टाइमलाइन वाला एक अकेला लंबा कॉलम। टिकट <code>ticket_number &mdash; subject</code> और शुरुआती समय दिखाने वाले बड़े ब्लॉक के रूप में रेंडर होते हैं; उसका विवरण खोलने या समय बदलने के लिए किसी एक पर क्लिक करें।',
            'rota_heading' => '<strong>स्टाफ़ रोटा</strong>',
            'rota_body' => 'रोटा पेज टीम लीड और मैनेजरों को सप्ताह भर में विश्लेषक शिफ्ट शेड्यूल करने देता है। मानक कार्य घंटे परिभाषित करें, ऑन-कॉल अवधि असाइन करें, और छुट्टी या अनुपस्थिति चिह्नित करें ताकि टीम को हमेशा पता रहे कि कौन उपलब्ध है।',
            'rota_step1' => '<strong>रोटा ग्रिड देखें</strong> &mdash; रोटा एक अक्ष पर विश्लेषकों और दूसरे पर दिनों को दिखाता है, शिफ्ट ब्लॉक एक नज़र में कवरेज दिखाते हुए।',
            'rota_step2' => '<strong>शिफ्ट जोड़ें या संपादित करें</strong> &mdash; शिफ्ट प्रकार असाइन करने के लिए किसी सेल पर क्लिक करें (जैसे Early, Late, Night, On-Call)। बदलाव तुरंत सहेजे जाते हैं।',
            'rota_step3' => '<strong>पहले से योजना बनाएँ</strong> &mdash; रोटा पहले से बनाने के लिए हफ़्ते दर हफ़्ते आगे नेविगेट करें। यह सुनिश्चित करता है कि व्यस्त अवधियों, छुट्टियों या ट्रेनिंग के दिनों में पर्याप्त कवरेज हो।',
            'rota_step4' => '<strong>एक साथ कई सेल भरें</strong> &mdash; किसी सेल में मौजूद शिफ्ट उठाने के लिए उस पर <strong>राइट-क्लिक</strong> करें और <em>Copy</em> चुनें, फिर किसी और पर राइट-क्लिक करके <em>Paste</em> करें। एक से ज़्यादा सेल के लिए, उनके एक ब्लॉक पर <strong>खींचकर चुनें</strong> (या एक-एक करके ctrl-क्लिक करें) और पूरे में पेस्ट करें। किसी <strong>दिन के हेडिंग</strong> पर होवर करने से वह पूरा दिन हाइलाइट हो जाता है, और किसी <strong>विश्लेषक के नाम</strong> पर होवर करने से उसका पूरा सप्ताह &mdash; दोनों में से किसी पर राइट-क्लिक करें और पूरे में पेस्ट करें। जहाँ कुछ सेल में पहले से ही शिफ्ट है, वहाँ मेनू सादे शब्दों में दोनों तरीके सुझाता है &mdash; <em>Paste into all 7</em> और <em>Paste into 6 empty cells</em> &mdash; ताकि आप बाद में नहीं, पहले ही चुन लें। अधिलेखित करने पर पुष्टि माँगी जाती है और बताया जाता है कि कितनी शिफ्ट बदली जाएँगी; खाली जगहें भरना बस हो जाता है, क्योंकि कुछ भी नहीं खोता। यही मेनू किसी दिन, सप्ताह या चुनाव को <strong>साफ़</strong> भी कर सकते हैं, फिर से यह बताने के बाद कि इससे कितनी शिफ्ट हटेंगी।',
            'rota_step5' => '<strong>एक व्यक्ति के लिए पूरा दिन या पूरा सप्ताह कॉपी करें</strong> &mdash; उस दिन की हर शिफ्ट उठाने के लिए किसी <strong>दिन के हेडिंग</strong> पर राइट-क्लिक करके <em>Copy</em> चुनें, या किसी <strong>विश्लेषक के नाम</strong> पर उसका पूरा सप्ताह उठाने के लिए। किसी और दिन, या किसी और विश्लेषक पर पेस्ट करने से यह मेल खा जाता है: जो शिफ्ट कॉपी में नहीं थीं वे साफ़ कर दी जाती हैं, ताकि आपको दोनों का मिश्रण नहीं बल्कि वही दिन मिले जो आपने कॉपी किया था। एक दिन को केवल किसी और दिन पर ही पेस्ट किया जा सकता है और एक विश्लेषक को केवल किसी और विश्लेषक पर &mdash; एक दिन <em>प्रति व्यक्ति</em> एक शिफ्ट है और एक सप्ताह <em>प्रति दिन</em> एक शिफ्ट, इसलिए एक को दूसरे पर रखने का कोई समझदार तरीका नहीं है। आज़माएँ और मेनू यही बताएगा, और यह भी बताएगा कि इसके बजाय यह कहाँ जा सकता है।',
            'rota_step6' => '<strong>पूरा सप्ताह कॉपी करें</strong> &mdash; ऊपर दाईं ओर <strong>Copy week</strong> और <strong>Paste week</strong> आप जो सप्ताह देख रहे हैं उसकी हर शिफ्ट उठाकर किसी और सप्ताह पर डाल देते हैं, जो दोहराई जाने वाली रोटा बनाने का सबसे तेज़ तरीका है। पेस्ट करना लक्ष्य सप्ताह की जगह <em>ले लेता है</em>, इसलिए पुष्टि आपको बताती है कि कितनी प्रविष्टियाँ हटने वाली हैं। यह केवल उन्हीं दिनों और लोगों को छूता है जो ग्रिड आपको वास्तव में दिखा रहा है।',
            'tip' => 'प्रभावी क्षमता योजना के लिए कैलेंडर और रोटा को साथ मिलाएँ। अगर कैलेंडर हर सोमवार सुबह टिकट में उछाल दिखाता है, तो सुनिश्चित करें कि रोटा में उस समय अतिरिक्त कवरेज शेड्यूल हो।',
        ],
        'settings' => [
            'heading' => 'सेटिंग्स',
            'intro' => 'Settings पेज वह जगह है जहाँ आप अपने टिकटिंग सिस्टम के बुनियादी हिस्से कॉन्फ़िगर करते हैं। सभी लुकअप मान, SLA लक्ष्य, ईमेल इंटीग्रेशन, और कस्टम फ़ील्ड यहीं प्रबंधित होते हैं।',
            'sla_callout_title' => 'SLA प्रबंधन &mdash; पूरी गाइड',
            'sla_callout_body' => 'कॉन्फ़िगर करने योग्य विकल्प, बिज़नेस कैलेंडर, पॉज़ स्थितियाँ, ब्रीच सूचनाएँ, cron job सेटअप, साथ ही एक ही टाइमज़ोन और क्रॉस-टाइमज़ोन टीमों के लिए काम किए हुए उदाहरण। अपने खुद के पेज लायक भारी विषय।',
            'card_dept_title' => 'विभाग',
            'card_dept_body' => 'IT, HR और Finance जैसे विभाग बनाएँ। हर विभाग इनबॉक्स में एक फ़ोल्डर और डैशबोर्ड पर एक फ़िल्टर बन जाता है',
            'card_types_title' => 'टिकट प्रकार',
            'card_types_body' => 'अपने डेस्क द्वारा संभाले जाने वाले अनुरोधों के प्रकार परिभाषित करें: Incident, Service Request, Problem, Change। प्रकार विश्लेषकों को काम वर्गीकृत करने में मदद करते हैं',
            'card_priorities_title' => 'प्राथमिकताएँ',
            'card_priorities_body' => 'नाम, रंग और क्रम के साथ प्राथमिकता स्तर सेट करें। हर प्राथमिकता जवाब और समाधान के लिए एक SLA लक्ष्य से जुड़ी है',
            'card_statuses_title' => 'स्थितियाँ',
            'card_statuses_body' => 'टिकट जीवनचक्र के चरण अनुकूलित करें। डिफ़ॉल्ट स्थितियों में New, Open, In Progress, Pending, Resolved, और Closed शामिल हैं',
            'card_categories_title' => 'श्रेणियाँ',
            'card_categories_body' => 'तकनीकी क्षेत्र के अनुसार टिकट समूहित करें: Hardware, Software, Network, Access। श्रेणियाँ रिपोर्टिंग विभाजन को शक्ति देती हैं',
            'card_sla_title' => 'SLA लक्ष्य',
            'card_sla_body' => 'प्रति प्राथमिकता जवाब और समाधान समय लक्ष्य परिभाषित करें। SLA टाइमर टिकट पर दिखते हैं और ब्रीच चेतावनियाँ चलाते हैं',
            'card_email_title' => 'ईमेल इम्पोर्टिंग',
            'card_email_body' => 'नई ईमेल को स्वचालित रूप से टिकट के रूप में इम्पोर्ट करने के लिए एक मेलबॉक्स (Exchange, Microsoft 365) कनेक्ट करें। जवाब मौजूदा टिकट में वापस थ्रेड होते हैं',
            'card_custom_title' => 'कस्टम फ़ील्ड',
            'card_custom_body' => 'अपने संगठन को चाहिए ऐसे डेटा के लिए टिकट में अपने खुद के फ़ील्ड जोड़ें जो डिफ़ॉल्ट फ़ील्ड सेट में शामिल नहीं है',
            'card_templates_title' => 'ईमेल टेम्पलेट',
            'card_templates_body' => 'टिकट बनने, अपडेट होने, हल होने, या CSAT सर्वेक्षण के लिए अंतिम उपयोगकर्ताओं को भेजे जाने वाले नोटिफ़िकेशन टेम्पलेट कॉन्फ़िगर करें। [requester_name] और [csat_link] जैसे मर्ज कोड जोड़ें',
            'card_checklists_title' => 'चेकलिस्ट',
            'card_checklists_body' => 'तय करें कि जब कोई ऐसा टिकट बंद करे जिस पर अनिवार्य चेकलिस्ट चरण अभी भी बचे हों तो क्या होता है: <strong>चेतावनी दें</strong> यानी चेतावनी देकर चरणों व बंद करने वाले के नाम के साथ एक आंतरिक नोट दर्ज करें, या <strong>रोकें</strong> यानी जब तक वे पूरे न हों तब तक बंद होने से रोकें। यह हर उस जगह लागू होता है जहाँ टिकट बंद किया जा सकता है - बल्क एक्शन, REST API और वर्कफ़्लो ऑटोमेशन शामिल।',
            'card_mandatory_title' => 'अनिवार्य फ़ील्ड',
            'card_mandatory_body' => 'उन फ़ील्ड को टिक करें जो टिकट बंद होने से पहले भरी जानी चाहिए - श्रेणी, समाधान कोड, स्वामी वगैरह। फिर तय करें कि जब कोई किसी फ़ील्ड को खाली रखकर टिकट बंद करे तो क्या होता है: <strong>चेतावनी दें</strong>, किसी सर्विस डिलीवरी मैनेजर जैसे व्यक्ति को <strong>चेतावनी दें और ईमेल करें</strong>, या बंद होना <strong>रोकें</strong>। एक अलग स्विच इसे टिकट पर आंतरिक नोट के रूप में दर्ज करता है। किसी कंपनी के लिए बंद की गई फ़ील्ड कभी आवश्यक नहीं होती, और टिकट मर्ज करना इसे कभी ट्रिगर नहीं करता। हर जगह लागू होता है जहाँ टिकट बंद किया जा सकता है - बल्क एक्शन, REST API और वर्कफ़्लो ऑटोमेशन सहित',
            'card_cleanup_title' => 'Reply Cleanup AI',
            'card_cleanup_body' => 'जवाब एडिटर पर ✨ Cleanup बटन के लिए Anthropic key + मॉडल + टोन। बारीक बिलिंग के लिए दूसरे AI फ़ीचर से अलग key',
            'card_csat_title' => 'CSAT',
            'card_csat_body' => 'भेजने का मोड (off / auto / manual), देरी, प्रति-टिकट-एक गार्ड, स्केल (stars या emojis)। पूरे फ़्लो के लिए सेक्शन 6 देखें',
            'email_heading' => '<strong>ईमेल इम्पोर्टिंग विस्तार से</strong>',
            'email_body' => 'ईमेल इम्पोर्ट फ़ीचर आपके शेयर्ड मेलबॉक्स से जुड़कर नए संदेशों को टिकट के रूप में लाता है। जब कोई अंतिम उपयोगकर्ता आपके सहायता पते (जैसे support@yourcompany.com) पर ईमेल भेजता है, तो FreeITSM ईमेल विषय को शीर्षक और ईमेल बॉडी को विवरण बनाकर एक टिकट बनाता है। अगर प्रेषक किसी सूचना ईमेल का जवाब देता है, तो वह जवाब डुप्लिकेट बनाने की बजाय मौजूदा टिकट में थ्रेड हो जाता है।',
            'email_step1' => '<strong>मेलबॉक्स कॉन्फ़िगर करें</strong> &mdash; Settings पर जाएँ और अपने Exchange या Microsoft 365 क्रेडेंशियल दर्ज करें। सुरक्षित, पासवर्ड-रहित कनेक्शन के लिए OAuth प्रमाणीकरण सपोर्ट किया जाता है।',
            'email_step2' => '<strong>पोलिंग अंतराल सेट करें</strong> &mdash; चुनें कि FreeITSM कितनी बार मेलबॉक्स में नए संदेशों की जाँच करे। छोटे अंतराल का मतलब है तेज़ टिकट निर्माण।',
            'email_step3' => '<strong>डिफ़ॉल्ट मैप करें</strong> &mdash; ईमेल से बने टिकट के लिए डिफ़ॉल्ट विभाग, प्रकार और प्राथमिकता सेट करें। विश्लेषक इम्पोर्ट के बाद इन्हें समायोजित कर सकते हैं।',
            'tip' => 'अंतिम उपयोगकर्ता संचार में पेशेवर, सुसंगत टोन बनाए रखने के लिए ईमेल टेम्पलेट का उपयोग करें। टेम्पलेट टिकट संदर्भ, अनुरोधकर्ता नाम, विश्लेषक नाम, और स्थिति के लिए डायनामिक प्लेसहोल्डर सपोर्ट करते हैं।',
            'closemsg_heading' => '<strong>टिकट बंद करते समय एक बार का संदेश</strong>',
            'closemsg_body' => '<code>[ticket_closed_message]</code> को किसी सक्रिय <strong>Ticket closed</strong> टेम्पलेट में कहीं भी डालें, और तब से, टिकट को बंद स्थिति में सेट करना विश्लेषक से एक वाक्य माँगता है - <em>&ldquo;the spare charger is on your desk&rdquo;</em>, <em>&ldquo;closing as agreed on the phone&rdquo;</em>। वे जो भी टाइप करें वह ठीक उसी जगह जाता है जहाँ आपने प्लेसहोल्डर रखा था, इसलिए उसके आस-पास के शब्दों पर नियंत्रण आपके पास ही रहता है। यह कोई सेटिंग नहीं है और कुछ भी इसे सहेजता नहीं: एक नोट, एक टिकट, एक ईमेल। कुछ भी टाइप न करें और वह लाइन बस वहाँ होती ही नहीं - न कोई खाली जगह, न कोई फ़ालतू विराम चिह्न।',
            'closemsg_note' => '<strong>यह प्रॉम्प्ट तभी दिखाई देता है जब प्लेसहोल्डर वाकई टेम्पलेट में मौजूद हो।</strong> इसके बिना, विश्लेषक ने जो भी टाइप किया होता वह चुपचाप फेंक दिया जाता, और जो भी डेस्क यह नहीं चाहता उसे हर एक बंद करने पर एक अतिरिक्त क्लिक मिल जाता। इसलिए जब आप इसे कॉन्फ़िगर करते हैं तो यह अपने आप चालू हो जाता है, और जब आप नहीं करते तो यह रास्ते से हट जाता है।',
            'cat_heading' => '<strong>श्रेणियाँ, और उनके साथ के दो फ़ील्ड</strong>',
            'cat_body' => 'टिकट का <em>प्रकार</em> बताता है कि यह किस तरह की चीज़ है; एक <em>श्रेणी</em> बताती है कि यह किस बारे में है। <strong>Settings &rarr; Categories</strong> के अंतर्गत सूची बनाएँ, साथ ही वे स्विच जो तय करते हैं कि इनमें से कुछ टिकट पर दिखेगा भी या नहीं।',
            'cat_card_one_title' => 'श्रेणी',
            'cat_card_one_body' => 'टिकट को दर्ज करते समय जो चुना गया कि यह किस रूप में रिपोर्ट किया गया। एक टिकट में ठीक एक होती है, इसलिए आपकी श्रेणियों की रिपोर्ट हमेशा वाकई हुए टिकटों की संख्या के बराबर आती है।',
            'cat_card_close_title' => 'समाप्ति पर श्रेणी',
            'cat_card_close_body' => 'टिकट खत्म होने पर वही सूची फिर से पूछी जाती है। आमतौर पर विश्लेषक बस उसकी पुष्टि करता है &mdash; यह उन मामलों में अपनी अहमियत साबित करता है जहाँ पहला अनुमान गलत था, जिससे आपको पता चलता है कि आपकी सैंतीस "printer problems" में से बारह असल में नेटवर्क की थीं।',
            'cat_card_res_title' => 'समाधान कोड',
            'cat_card_res_body' => 'टिकट किस बारे में था इसकी बजाय यह कैसे खत्म हुआ &mdash; "Fixed remotely", "Training given", "No fault found"। शुरुआत से ही दस समझदार विकल्प मौजूद हैं और आप उन सभी को बदल सकते हैं।',
            'cat_rule_off' => '<strong>तीनों शुरुआत में बंद रहते हैं।</strong> पहले अपनी सूची बनाएँ, फिर जो चाहिए उन्हें चालू करें। हर एक को हर कंपनी के लिए अलग सेट किया जा सकता है।',
            'cat_rule_levels' => 'श्रेणियों की तीन स्तर तक उप-श्रेणियाँ हो सकती हैं, और कोई भी स्तर अनिवार्य नहीं है।',
            'cat_rule_type' => 'एक श्रेणी को एक टिकट प्रकार से जोड़ा जा सकता है, इसलिए "User onboarding" केवल एक service request पर दी जाती है। यह जुड़ाव शीर्ष-स्तर श्रेणी का होता है और उसकी उप-श्रेणियाँ इसे मानती हैं।',
            'cat_rule_typechange' => '<strong>टिकट का प्रकार बदलने से पुराने प्रकार से जुड़ी श्रेणी हट जाती है</strong>, और स्क्रीन पर यह बता भी दिया जाता है। किसी प्रकार से न जुड़ी श्रेणी बदलाव के बाद भी बनी रहती है।',
            'cat_rule_portal' => 'सेल्फ-सर्विस पोर्टल में एक श्रेणी देने के लिए <em>Customers can pick this</em> टिक करें। अनुरोधकर्ता सादी भाषा में एक छोटी सूची देखते हैं जबकि विश्लेषक पूरा ट्री देखते हैं।',
            'cat_rule_retire' => 'किसी श्रेणी को रिटायर करने के लिए बंद करें &mdash; यह उन टिकटों पर बनी रहती है जिनमें यह पहले से है और नए पर देने से रुक जाती है। यह हटाने से लगभग हमेशा बेहतर है, जो तब तक मना कर दिया जाता है जब तक कोई इसका उपयोग कर रहा हो।',
            'cat_rule_report' => 'तीनों को टिकट डैशबोर्ड पर चार्ट किया जा सकता है। दोनों श्रेणी चार्ट शीर्ष स्तर तक रोल-अप होते हैं, और जिन टिकटों में कुछ भी सेट नहीं है उन्हें छिपाने की बजाय <em>Not categorised</em> के रूप में गिना जाता है।',
            'cat_tip' => 'अगर पक्का नहीं कि कहाँ से शुरू करें, तो श्रेणियाँ खाली छोड़ें और अकेले <strong>Resolution code</strong> चालू करें। यह वह फ़ील्ड है जो सबसे तेज़ी से आपके काम करने का तरीका बदलती है &mdash; आपके पाँचवें हिस्से टिकट "Training given" के रूप में वापस आना एक दस्तावेज़ीकरण समस्या है, IT की नहीं।',
        ],
        'tips' => [
            'heading' => 'त्वरित सुझाव',
            'search_title' => 'सब कुछ खोजें',
            'search_body' => 'खोज मॉडल टिकट संदर्भ, विषय, अनुरोधकर्ता के नाम, और ईमेल पते जाँचता है। जब कोई उपयोगकर्ता किसी मौजूदा समस्या के बारे में कॉल करे तो संबंधित टिकट जल्दी ढूँढ़ने के लिए इसका उपयोग करें।',
            'sla_title' => 'अपने SLA पर नज़र रखें',
            'sla_body' => 'SLA टाइमर हर टिकट पर रीडिंग पेन में दिखते हैं। रंग-कोडेड संकेतक ब्रीच नज़दीक आने पर एम्बर और लक्ष्य छूटने पर लाल हो जाते हैं, ताकि आप उसी हिसाब से प्राथमिकता तय कर सकें।',
            'reply_title' => 'इनबॉक्स से जवाब दें',
            'reply_body' => 'अंतिम उपयोगकर्ता को जवाब देने के लिए अपना ईमेल क्लाइंट खोलने की ज़रूरत नहीं। सीधे संदेश भेजने के लिए रीडिंग पेन में Reply बटन का उपयोग करें। यह अपने आप टिकट में थ्रेड हो जाता है।',
            'trail_title' => 'गतिविधि ट्रेल का उपयोग करें',
            'trail_body' => 'किसी टिकट पर काम करने से पहले, उसका गतिविधि ट्रेल स्क्रॉल करें। पिछले विश्लेषक के नोट, ईमेल, और फ़ील्ड बदलाव आपको पूरा संदर्भ देते हैं ताकि आपको उपयोगकर्ता से जानकारी दोहराने के लिए न कहना पड़े।',
            'dash_title' => 'मैनेजरों के लिए डैशबोर्ड',
            'dash_body' => 'SLA अनुपालन दर, औसत समाधान समय, और विभाग के अनुसार टिकट के लिए विजेट वाला एक डैशबोर्ड बनाएँ। लगातार सुधार लाने के लिए टीम मीटिंग में इसे साझा करें।',
            'rota_title' => 'रोटा के साथ योजना बनाएँ',
            'rota_body' => 'रोटा को कम से कम दो हफ़्ते पहले भरें। कैलेंडर दृश्य के साथ मिलाने पर, यह रिस्पॉन्स टाइम के लिए समस्या बनने से पहले कवरेज में कमी पहचानने में मदद करता है।',
            'drag_title' => 'ट्राइएज के लिए खींचें',
            'drag_body' => 'टिकट को खोले बिना अपडेट करने के लिए उन्हें सूची से फ़ोल्डर पर खींचें। विभाग + स्थिति उप-फ़ोल्डर दोनों को एक साथ अपडेट करते हैं। स्प्रिंग-लोडेड विस्तार ड्रैग के बीच में नेस्टेड स्थितियों को पहुँच योग्य बनाता है।',
            'dbl_title' => 'फ़ुल स्क्रीन के लिए डबल-क्लिक',
            'dbl_body' => 'सिंगल-क्लिक रीडिंग पेन में टिकट का पूर्वावलोकन दिखाता है; डबल-क्लिक ध्यान केंद्रित करने वाले काम के लिए इसे फ़ुल-स्क्रीन मोड में खोलता है। वापस टॉगल करने के लिए विषय के बगल में मैक्सिमाइज़ आइकन क्लिक करें।',
            'rightclick_title' => 'त्वरित कार्रवाइयों के लिए राइट-क्लिक',
            'rightclick_body' => 'किसी टिकट पर एक-क्लिक में स्थिति, प्राथमिकता, या असाइनी बदलने के साथ-साथ CMDB लिंक और समय दर्ज करने के लिए राइट-क्लिक करें, यह सब उस टिकट से बिना हटे जिसे आप अभी पढ़ रहे हैं।',
            'ai_title' => 'AI से अपना जवाब साफ़ करवाएँ',
            'ai_body' => 'एक कच्चा ड्राफ्ट (या सिर्फ़ बुलेट पॉइंट) टाइप करें और <strong>✨ Cleanup</strong> क्लिक करें &mdash; Claude इसे अभिवादन, व्याकरण सुधार, और साइन-ऑफ के साथ एक उचित ईमेल के रूप में फिर से लिखता है। Undo लिंक 30 सेकंड के लिए दिखता है।',
            'feedback_title' => 'फ़ीडबैक माँगें',
            'feedback_body' => 'टिकट बंद होने पर अनुरोधकर्ताओं का ऑटो-सर्वे करने के लिए <strong>Settings &rarr; CSAT</strong> के अंतर्गत CSAT चालू करें। प्रति-विश्लेषक रुझान <code>tickets/csat/</code> पर मिलते हैं &mdash; विकास संबंधी बातचीत के लिए बेहद उपयोगी।',
            'precreate_title' => 'अंतिम उपयोगकर्ताओं को पहले से बनाएँ',
            'precreate_body' => '<strong>Users</strong> नैव बटन आपको उपयोगकर्ता को टिकट दर्ज करने की ज़रूरत पड़ने से पहले ही जोड़ने देता है &mdash; पासवर्ड खाली छोड़ें और वे खुद सेल्फ-सर्विस पोर्टल से अकाउंट क्लेम कर सकते हैं।',
        ],
        'companies' => [
            'heading' => 'कंपनियाँ &amp; ईमेल रूटिंग',
            'intro' => 'जब आपका इंस्टॉल एक से ज़्यादा कंपनी को सर्व करता है (उदाहरण के लिए कई क्लाइंट को सपोर्ट करने वाला कोई IT प्रोवाइडर), तो हर कंपनी के टिकट अलग रखे जाते हैं। यह सेक्शन बताता है कि इनबाउंड ईमेल सही कंपनी कैसे ढूँढ़ती है।',
            'switcher_body' => 'हेडर में एक <strong>कंपनी स्विचर</strong> दिखता है। यह वह कंपनी सेट करता है जिसमें आप काम कर रहे हैं &mdash; टिकट सूची, फ़ोल्डर और गणनाएँ सब उसी कंपनी की दिखाते हैं, और आप जो भी टिकट बनाएँ वह उसी में दर्ज होता है। कई कंपनियों तक एक्सेस वाला स्टाफ़ उनके बीच स्विच कर सकता है; वर्तमान कंपनी हमेशा दिखती है ताकि आप गलत संदर्भ में जवाब न दें। कंपनियों को खुद <strong>System &rarr; Companies</strong> के अंतर्गत प्रबंधित करें।',
            'mailboxes_heading' => 'हर मेलबॉक्स दो में से एक तरह का होता है &mdash; यही रूटिंग तय करता है:',
            'card_pinned_title' => 'पिन किया गया मेलबॉक्स',
            'card_pinned_body' => 'एक कंपनी के लिए समर्पित (जैसे किसी क्लाइंट का अपना <code>itsupport@</code>)। इसकी <strong>सारी</strong> मेल उसी कंपनी में दर्ज होती है &mdash; प्रेषक की अनदेखी की जाती है &mdash; और जवाब उसी से बाहर जाते हैं, ताकि क्लाइंट को शुरू से आखिर तक अपना ही हेल्प डेस्क दिखे।',
            'card_shared_title' => 'शेयर्ड इनटेक मेलबॉक्स',
            'card_shared_body' => 'एक पता जो कई कंपनियों को सर्व करता है (जैसे किसी प्रोवाइडर का एक अकेला <code>support@theprovider.com</code>)। यह अकेले पते से कंपनी नहीं जान सकता, इसलिए यह इसे <strong>ईमेल भेजने वाला कौन है</strong> इससे तय करता है। कई क्लाइंट वाले प्रोवाइडर के लिए अनुशंसित सेटअप।',
            'routing_heading' => 'शेयर्ड-इनटेक मेलबॉक्स कंपनी कैसे चुनता है',
            'routing_body' => 'हर इनकमिंग ईमेल के लिए यह इन्हें क्रम में आज़माता है, और पहला मिलान जीतता है:',
            'flow_reply' => 'किसी टिकट का जवाब',
            'flow_sender' => 'ज्ञात प्रेषक',
            'flow_domain' => 'ज्ञात डोमेन',
            'flow_triage' => 'ट्राइएज',
            'rule_reply' => '<strong>1. किसी मौजूदा टिकट का जवाब</strong> &mdash; अपने संदर्भ से पहचाना गया, ईमेल उस टिकट में शामिल हो जाती है और उसकी कंपनी बनाए रखती है।',
            'rule_sender' => '<strong>2. किसी कंपनी से जुड़ा एक विशिष्ट प्रेषक पता</strong> (जैसे <code>jane@gmail.com</code> &rarr; Acme) &mdash; वही कंपनी। यह डोमेन से पहले जाँचा जाता है, इसलिए यह निजी/वेबमेल पतों के लिए भी काम करता है।',
            'rule_domain' => '<strong>3. प्रेषक का डोमेन</strong> किसी कंपनी से जुड़ा (जैसे कोई भी <code>@acme.com</code> &rarr; Acme) &mdash; वही कंपनी।',
            'rule_triage' => '<strong>4. कोई मिलान नहीं</strong> &mdash; ईमेल खोने की बजाय <strong>ट्राइएज</strong> कतार में चली जाती है (नीचे देखें)।',
            'keys_heading' => 'डोमेन &amp; विशिष्ट प्रेषक (हर कंपनी के लिए System &rarr; Companies के अंतर्गत सेट)',
            'keys_body' => 'ये वे कुंजियाँ हैं जिनसे शेयर्ड-इनटेक मेलबॉक्स मिलान करता है। हर कंपनी उन ईमेल डोमेन को सूचीबद्ध करती है जिनकी वह मालिक है और, वैकल्पिक रूप से, अलग-अलग प्रेषक पते।',
            'card_domains_title' => 'ईमेल डोमेन',
            'card_domains_body' => 'किसी कंपनी के मालिकाना डोमेन (acme.com, acme.co.uk)। किसी पंजीकृत डोमेन पर कोई भी प्रेषक उसी कंपनी में रूट होता है। एक डोमेन केवल एक कंपनी का होता है।',
            'card_senders_title' => 'विशिष्ट प्रेषक',
            'card_senders_body' => 'किसी कंपनी से जुड़े अलग-अलग पते, डोमेन से पहले जाँचे जाते हैं। किसी फ्रीलांसर या निजी पते से ईमेल करने वाले किसी छोटे क्लाइंट के लिए उपयोग करें।',
            'card_public_title' => 'सार्वजनिक प्रोवाइडर',
            'card_public_body' => 'Gmail, Outlook, Yahoo और इस जैसों को डोमेन के रूप में मैप नहीं किया जा सकता (कई असंबंधित लोग इन्हें साझा करते हैं) &mdash; इसकी बजाय सटीक पते को विशिष्ट प्रेषक के रूप में मैप करें।',
            'triage_heading' => 'ट्राइएज कतार &mdash; सुरक्षा जाल',
            'triage_body' => 'जब कोई शेयर्ड-इनटेक ईमेल किसी कंपनी से मेल नहीं खाती, तो वह खोने की बजाय <strong>Triage</strong> (कंपनी स्विचर से पहुँचा जा सकता है, एक लाइव गिनती के साथ) में उतरती है। हर आइटम प्रेषक, डोमेन, विषय और यह किस मेलबॉक्स पर आई दिखाता है। इसे एक कदम में किसी कंपनी में फ़ाइल करें:',
            'triage_create' => 'किसी मौजूदा कंपनी को चुनें, या मौके पर एक नई बनाएँ।',
            'triage_assign' => 'किसी सामान्य डोमेन के लिए, वैकल्पिक रूप से <strong>उस डोमेन को रूट करें</strong> कंपनी की ओर; किसी सार्वजनिक/वेबमेल पते के लिए, वैकल्पिक रूप से <strong>हमेशा उस प्रेषक को फ़ाइल करें</strong> वहाँ।',
            'triage_sweep' => 'दोनों में से कोई भी चुनाव <em>स्वीप</em> करता है: यह उस डोमेन या पते से हर दूसरी कतार में पड़ी ईमेल को भी हटा देता है और भविष्य की मेल को स्वतः रूट करता है &mdash; इसलिए आप किसी दिए गए प्रेषक को केवल एक बार सुलझाते हैं।',
            'triage_tip' => 'कुछ भी कभी खोता नहीं है। बेमेल मेल तब तक ट्राइएज में इंतज़ार करती है जब तक कोई उसे फ़ाइल न करे; बिना फ़ाइल किया गया टिकट इस बीच डिफ़ॉल्ट कंपनी के अंतर्गत दिखता रहता है।',
            'test_heading' => 'लाइव जाने से पहले अपनी रूटिंग जाँचें',
            'test_body' => '<strong>System &rarr; Email routing test</strong> के अंतर्गत आप एक ईमेल के आने का नाटक कर सकते हैं &mdash; एक मेलबॉक्स चुनें, एक प्रेषक पता टाइप करें &mdash; और ठीक-ठीक देखें कि नया टिकट किस कंपनी में उतरेगा (या यह ट्राइएज में जाएगा) और किस नियम ने यह तय किया। यह कुछ भी नहीं बनाता; यह बस आपकी सेटिंग्स पढ़ता है।',
            'settings_heading' => 'सेटिंग्स: डिफ़ॉल्ट रूप से साझा, जहाँ ज़रूरी हो वहाँ अनुकूलित',
            'settings_body' => 'इनमें से कुछ Settings को <strong>प्रति कंपनी अनुकूलित</strong> किया जा सकता है; बाकी जान-बूझकर साझा रहती हैं। जहाँ कोई सेटिंग विकल्पों की एक सादी सूची है &mdash; जैसे <strong>ticket types</strong> और <strong>origins</strong> &mdash; किसी कंपनी के संदर्भ में स्विच करें और आपको साझा डिफ़ॉल्ट (हर एक के साथ किसी को छिपाने के लिए एक आँख आइकन) के साथ-साथ कंपनी ने खुद के लिए जो जोड़ा है वह भी दिखेगा। किसी विकल्प को तब तक छिपाया या हटाया नहीं जा सकता जब तक खुले टिकट उसका उपयोग कर रहे हों, और साझा डिफ़ॉल्ट खुद MSP / डिफ़ॉल्ट कंपनी से संपादित होते हैं।',
            'settings_custom_title' => 'प्रति कंपनी अनुकूलित',
            'settings_custom_body' => 'टिकट प्रकार &amp; स्रोत (अभी), और श्रेणियाँ, SLA व कार्य-घंटे (आने वाले) &mdash; ऐसी चीज़ें जो वाकई एक क्लाइंट से दूसरे में अलग होती हैं।',
            'settings_global_title' => 'हर कंपनी में साझा',
            'settings_global_body' => 'स्थितियाँ और प्राथमिकताएँ हर जगह एक जैसी रहती हैं, ताकि क्रॉस-कंपनी रिपोर्टिंग और SLA सुसंगत रहें; आपकी टीमें, रोटा और मेलबॉक्स भी वैसे ही रहते हैं &mdash; यह आपका अपना संचालन है, किसी क्लाइंट का नहीं।',
            'allview_heading' => '<strong>हर कंपनी में एक बोर्ड</strong>',
            'allview_body' => 'हेडर में कंपनी स्विचर में एक <strong>All companies</strong> विकल्प है। आपको देखने की अनुमति वाला हर टिकट एक ही सूची में दिखता है, हर रो अपनी कंपनी पहनकर &mdash; तब उपयोगी जब आप कई इकाइयों को सपोर्ट करते हैं और किसका क्या है यह न भूलते हुए पूरे दिन का एक ही दृश्य चाहते हैं।',
            'allview_card_scope_title' => 'यह कुछ भी नया नहीं देता',
            'allview_card_scope_body' => '"All" का मतलब है वे सारी कंपनियाँ जिन तक आप पहले से एक-एक करके पहुँच सकते थे। जो विश्लेषक आपकी तीन में से दो इकाइयों को सपोर्ट करता है वह ठीक वही दो देखता है, और एक कंपनी वाला विश्लेषक उसी एक कंपनी का दृश्य देखता है।',
            'allview_card_props_title' => 'हर इकाई अलग रहती है',
            'allview_card_props_body' => 'किसी टिकट को खोलें और उसका प्रकार, स्रोत, श्रेणी और समाधान सूची <em>उसी</em> कंपनी की होती है &mdash; इसलिए एक इकाई के पास मौजूद और दूसरी के पास न मौजूद कोई श्रेणी कभी गलत टिकट पर लागू नहीं हो सकती।',
            'allview_card_new_title' => 'नए टिकट पूछते हैं कि कौन सी कंपनी',
            'allview_card_new_body' => 'मान लेने के लिए कोई एक सक्रिय कंपनी नहीं है, और यह चुनाव टिकट संख्या, वह मेलबॉक्स जिससे जवाब आते हैं, और लागू होने वाला SLA तय करता है। कंपनी चुनते ही प्रकार सूची भर जाती है।',
            'allview_rule_chip' => 'ईमेल या पोर्टल से बिना अभी रूट हुए आया कोई टिकट Default के अंतर्गत दिखाने की बजाय <strong>Unrouted</strong> चिह्नित होता है, ताकि वह ट्राइएज के लिए अलग दिखे।',
            'allview_rule_reply' => 'जवाब अब भी उसी मेलबॉक्स से बाहर जाते हैं जिस पर टिकट आया था &mdash; यह टिकट का अनुसरण करता है, दृश्य का नहीं, ताकि संयुक्त बोर्ड कभी गलत पते से न भेजे।',
            'allview_rule_knowledge' => '<strong>Ask AI</strong> संयुक्त दृश्य चालू होने पर आपको दिखने वाली हर कंपनी में खोजता है, न कि केवल एक में। सभी कंपनियों के साथ साझा किए गए लेख दोनों ही तरह शामिल रहते हैं।',
            'allview_rule_trash' => '<strong>ट्रैश खाली करना कभी भी कंपनियों में नहीं फैलता।</strong> यह हमेशा उस एक कंपनी पर लागू होता है जिसे आपने आखिरी बार चुना था, क्योंकि कई इकाइयों में एक साथ "delete everything in the bin" करना किसी का भी मतलब नहीं होता।',
            'allview_rule_other' => 'केवल टिकट सूची चौड़ी होती है। Assets, Changes, Tasks और CMDB अब भी एक बार में एक ही कंपनी दिखाते हैं &mdash; उनमें काम करने के लिए उस कंपनी पर स्विच करें।',
            'privacy_heading' => 'हर कंपनी के टिकट निजी रहते हैं',
            'privacy_body' => 'जब आप किसी कंपनी के संदर्भ में काम कर रहे हों तो आपको हमेशा केवल <strong>उसी</strong> कंपनी के टिकट दिखते हैं &mdash; सूची में, खोज में, डैशबोर्ड पर, और आपके खोले हर टिकट पर (उसकी ईमेल, अनुलग्नक, नोट और इतिहास सहित)। कोई स्टाफ़ सदस्य किसी टिकट तक तभी पहुँच सकता है जब उसे उस कंपनी की एक्सेस दी गई हो (आप हर विश्लेषक की कंपनियाँ System &rarr; Analysts के अंतर्गत चुनते हैं, या System &rarr; Teams पर पूरी टीम को दे सकते हैं), इसलिए किसी दूसरे क्लाइंट के डेटा में भटकने का कोई रास्ता नहीं है। यह अलगाव हर जगह पर्दे के पीछे लागू होता है, सिर्फ़ दृश्य से छिपाया नहीं जाता। एक सिंगल-कंपनी इंस्टॉल पर यह स्वचालित और अदृश्य है &mdash; क्योंकि वहाँ केवल एक ही कंपनी है, तो सब कुछ बस उसी का होता है।',
            'tip' => 'एक सिंगल-कंपनी इंस्टॉल पर इनमें से कुछ भी नहीं दिखता &mdash; एक ही कंपनी है, हर टिकट उसी का है, और कोई स्विचर या ट्राइएज नहीं है। ये फ़ीचर तभी चालू होते हैं जब दूसरी कंपनी मौजूद हो।',
        ],
    ],
    'help_sla' => [
        'page_title' => 'सेवा डेस्क - SLA प्रबंधन',
        'back_link' => '&larr; टिकट गाइड पर वापस',
        'sidebar_title' => 'SLA गाइड',
        'hero_title' => 'SLA प्रबंधन',
        'hero_sub' => 'व्यावसायिक घंटों के अनुसार प्रतिक्रिया और समाधान लक्ष्य, प्रति-विभाग SLA उल्लंघन सूचनाओं के साथ',
        'nav' => [
            'overview' => 'अवलोकन',
            'building_blocks' => 'मूल घटक',
            'behaviour_settings' => 'व्यवहार सेटिंग्स',
            'breach_notifications' => 'उल्लंघन सूचनाएँ',
            'cron_setup' => 'Cron job सेटअप',
            'worked_examples' => 'व्यावहारिक उदाहरण',
            'troubleshooting' => 'समस्या निवारण',
        ],
        'overview' => [
            'heading' => 'अवलोकन',
            'sub' => 'SLA क्या होते हैं, ये क्यों महत्वपूर्ण हैं, और FreeITSM इंजन सामान्य स्तर पर कैसे काम करता है।',
            'p1' => 'एक Service Level Agreement (SLA) यह वादा है कि आपकी टीम किसी टिकट पर कितनी जल्दी प्रतिक्रिया देगी और उसे हल करेगी। FreeITSM प्रति टिकट दो घड़ियाँ ट्रैक करता है: <strong>प्रतिक्रिया</strong> (टिकट बनने से पहली विश्लेषक कार्रवाई तक का समय) और <strong>समाधान</strong> (टिकट बनने से टिकट बंद होने तक का समय)। दोनों लक्ष्य प्रति प्राथमिकता सेट किए जाते हैं &mdash; इसलिए किसी P1 के लिए प्रतिक्रिया हेतु 30 मिनट और समाधान हेतु 4 घंटे हो सकते हैं, जबकि किसी P4 के लिए 8 कार्य-घंटे और 5 कार्य-दिवस हो सकते हैं।',
            'p2' => 'FreeITSM के SLA इंजन में चार डिज़ाइन निर्णय हैं जिन्हें समझना ज़रूरी है:',
            'choice_business' => '<strong>वॉल क्लॉक नहीं, व्यावसायिक घंटे।</strong> यदि 1 घंटे के प्रतिक्रिया लक्ष्य वाला कोई P2 टिकट शाम 4:30 बजे उठाया जाता है और ऑफिस शाम 5 बजे बंद हो जाता है, तो यह शाम 5:30 बजे उल्लंघन नहीं होता। घड़ी अगले कार्य-दिवस सुबह 9 बजे फिर से चलने लगती है। यह इंडस्ट्री मानक है और रात में घर जाने वाले विश्लेषकों के लिए एकमात्र निष्पक्ष मॉडल है।',
            'choice_pause' => '<strong>रोकी जा सकने वाली।</strong> जब कोई टिकट "Pause SLA" के रूप में चिह्नित किसी स्थिति में होता है (जैसे <em>Awaiting Response</em> या <em>On Hold</em>), तो घड़ी रुक जाती है। टिकट के किसी कार्यशील स्थिति में वापस आने पर यह फिर से चलने लगती है।',
            'choice_compute' => '<strong>Compute-on-read, संग्रहीत नहीं।</strong> इंजन हर बार देखने पर टिकट के ऑडिट लॉग से SLA स्थिति की फिर से गणना करता है। कोई संग्रहीत काउंटर नहीं है जो सिंक से बाहर हो सके। यदि आप बाद में किसी व्यावसायिक कैलेंडर के घंटे बदलते हैं, तो अगली बार देखे जाने पर हर पुराने टिकट का SLA नए घंटों के अनुसार फिर से गणना किया जाता है।',
            'choice_cutoff' => '<strong>Enforcement cutoff.</strong> एडमिन द्वारा नियंत्रित "Enforce SLAs from" तिथि का मतलब है कि जब आप SLA चालू करते हैं तो आपके सिस्टम के मौजूदा टिकट अचानक पिछली तारीख से उल्लंघन में नहीं आ जाते। केवल कटऑफ पर या उसके बाद बनाए गए टिकट ही ट्रैक किए जाते हैं।',
            'tip' => 'यदि आप ITIL के लिए नए हैं: प्रतिक्रिया समय स्वीकृति के बारे में है (किसी ने टिकट को उठाया); समाधान समय पूर्णता के बारे में है (उपयोगकर्ता की समस्या ठीक हो गई)। दोनों घड़ियाँ स्वतंत्र रूप से चलती हैं और उनके लक्ष्य अलग-अलग होते हैं।',
        ],
        'blocks' => [
            'heading' => 'चार मूल घटक',
            'sub' => 'इन चार चीज़ों को कॉन्फ़िगर करें और SLA ट्रैकिंग शुरू हो जाएगी। बाकी सब वैकल्पिक परिष्करण है।',
            'cal_heading' => '1. व्यावसायिक कैलेंडर',
            'cal_intro' => 'एक कैलेंडर यह तय करता है कि आपका सर्विस डेस्क कब खुला रहता है। प्रत्येक कैलेंडर में होता है:',
            'cal_tz' => '<strong>Timezone</strong> &mdash; एक IANA timezone identifier (जैसे <code>Europe/London</code>, <code>America/New_York</code>, <code>Asia/Singapore</code>)। DST परिवर्तन स्वचालित रूप से संभाले जाते हैं।',
            'cal_hours' => '<strong>साप्ताहिक कार्य-घंटे</strong> &mdash; प्रत्येक सप्ताह के दिन के लिए एक पंक्ति, जिसमें एक Open चेकबॉक्स और आरंभ/समाप्ति समय होते हैं। नए कैलेंडर डिफ़ॉल्ट रूप से Mon-Fri 09:00-17:00 पर सेट होते हैं, Sat/Sun बंद रहते हैं। जिस पंक्ति में Open चिह्नित नहीं है, उस दिन डेस्क बंद माना जाता है।',
            'cal_holidays' => '<strong>अवकाश (Holidays)</strong> &mdash; तिथि + वैकल्पिक नाम। अवकाश साप्ताहिक पैटर्न को ओवरराइड करते हैं (भले ही वह सोमवार को पड़े, डेस्क बंद रहेगा)।',
            'cal_default' => '<strong>Default फ़्लैग</strong> &mdash; ठीक एक कैलेंडर डिफ़ॉल्ट होता है। जब तक अन्यथा निर्दिष्ट न करें, नई प्राथमिकताएँ इसे इनहेरिट करती हैं।',
            'cal_outro' => 'आप जितने चाहें उतने कैलेंडर बना सकते हैं &mdash; प्रति ऑफिस एक, प्रति टीम एक, या विस्तारित घंटों वाले VIP ग्राहकों के लिए एक। इन्हें SLA लक्ष्यों और breach-check इंजन द्वारा साझा किया जाता है।',
            'prio_heading' => '2. SLA लक्ष्यों वाली प्राथमिकताएँ',
            'prio_intro' => 'Priorities टैब पर (या SLA टैब की SLA Targets तालिका के ज़रिए), प्रत्येक प्राथमिकता में ये हो सकते हैं:',
            'prio_response' => '<strong>प्रतिक्रिया लक्ष्य (मिनट)</strong> &mdash; पहली विश्लेषक कार्रवाई तक कितना समय।',
            'prio_resolution' => '<strong>समाधान लक्ष्य (मिनट)</strong> &mdash; टिकट बंद होने तक कितना समय।',
            'prio_calendar' => '<strong>कैलेंडर</strong> &mdash; यह प्राथमिकता किस व्यावसायिक कैलेंडर के अनुसार चलती है। डिफ़ॉल्ट कैलेंडर उपयोग करने के लिए खाली छोड़ें।',
            'prio_outro' => 'दोनों लक्ष्य फ़ील्ड खाली छोड़ने पर उस प्राथमिकता के लिए SLA ट्रैकिंग पूरी तरह बंद हो जाती है &mdash; यह "Informational" या "Backlog" जैसी प्राथमिकता के लिए उपयोगी है जहाँ समय का दबाव नहीं होता।',
            'pause_heading' => '3. Pause-SLA स्थितियाँ',
            'pause_intro' => 'Statuses टैब पर एक समर्पित "Pause SLA" कॉलम है। किसी भी ऐसी स्थिति को चिह्नित करें जो दर्शाती है कि टिकट टीम के नियंत्रण से बाहर किसी चीज़ पर अटका है। सामान्य उम्मीदवार हैं:',
            'pause_awaiting' => '<strong>Awaiting Response</strong> &mdash; ग्राहक से जानकारी मिलनी बाकी है। लगभग सार्वभौमिक रूप से एक निष्पक्ष पॉज़ माना जाता है।',
            'pause_vendor' => '<strong>On Hold (Vendor)</strong> &mdash; Microsoft / थर्ड-पार्टी सपोर्ट का इंतज़ार।',
            'pause_change' => '<strong>On Hold (Change Window)</strong> &mdash; भविष्य की मेंटेनेंस विंडो के लिए निर्धारित।',
            'pause_parts' => '<strong>On Hold (Parts)</strong> &mdash; हार्डवेयर डिलीवरी का इंतज़ार।',
            'pause_warn' => 'एक सामान्य "On Hold" स्थिति का दुरुपयोग SLA से बचने के रास्ते के रूप में किया जा सकता है, खासकर जब टिकट कठिन हो या विश्लेषक व्यस्त हो। यदि आपकी टीम अनुशासित है, तो यह ठीक है। यदि नहीं, तो इसे ऊपर बताए गए अधिक विशिष्ट विकल्पों से बदलने पर विचार करें, या <strong>Watchtower</strong> डैशबोर्ड पर भरोसा करें जो 24 घंटे से ज़्यादा पॉज़ रहे टिकटों को amber अलर्ट के रूप में चिह्नित करता है।',
            'cutoff_heading' => '4. Enforcement Cutoff (<code>Enforce SLAs from</code>)',
            'cutoff_p1' => 'सबसे महत्वपूर्ण वैश्विक सेटिंग। जब तक आप यहाँ कोई datetime सेट नहीं करते, SLA ट्रैकिंग पूरी तरह बंद रहती है &mdash; कोई घड़ी नहीं चलती, इनबॉक्स पर कोई pill नहीं दिखती, कोई उल्लंघन ईमेल नहीं भेजी जाती। इसे किसी पिछली तारीख पर सेट करने से SLA उसी तारीख से पूर्वव्यापी रूप से चालू हो जाते हैं। इसे किसी भविष्य की तारीख पर सेट करने से चालू होने का समय निर्धारित हो जाता है।',
            'cutoff_p2' => 'अधिकांश टीमें SLA को पहली बार चालू करते समय इसे "अभी" पर सेट करती हैं &mdash; मौजूदा टिकट अपनी पूर्व-SLA स्थिति में रहते हैं, और उस पल से आगे बनने वाले नए टिकट ट्रैक होने लगते हैं।',
        ],
        'behaviour' => [
            'heading' => 'व्यवहार सेटिंग्स',
            'sub' => 'ये नियंत्रित करती हैं कि इंजन एज केस पर कैसे प्रतिक्रिया करता है। डिफ़ॉल्ट मान समझदारी से चुने गए हैं &mdash; इन्हें बदलने की ज़रूरत तभी है जब आपकी कोई विशेष प्राथमिकता हो।',
            'prio_heading' => 'जब बीच में प्राथमिकता बदल जाए',
            'prio_intro' => 'यदि कोई P3 टिकट बीच में P1 में अपग्रेड हो जाता है (क्योंकि समस्या सोचे गए से बड़ी निकली), तो तीन उचित व्यवहार संभव हैं:',
            'prio_forward' => '<strong>Forward (डिफ़ॉल्ट)</strong> &mdash; अर्जित व्यावसायिक मिनटों को बनाए रखें और केवल लक्ष्य फिर से सेट करें। यदि टिकट ने अपने 8 घंटे के P3 लक्ष्य में से 2 घंटे उपयोग कर लिए थे, तो अब उसके 1 घंटे के P1 लक्ष्य के मुक़ाबले 2 घंटे उपयोग हो चुके हैं &mdash; यानी वह पहले ही उल्लंघन में है। तर्क के अनुसार यह सही है: समस्या शुरू से ही P1 थी, टीम को बस इसका पता नहीं था।',
            'prio_recompute' => '<strong>Recompute</strong> &mdash; घड़ी रीसेट करें और नया लक्ष्य टिकट बनने के समय से पूर्वव्यापी रूप से लागू करें। एक स्वच्छ पुनर्गणना।',
            'prio_reset' => '<strong>Reset</strong> &mdash; प्राथमिकता बदलने के क्षण से नई घड़ी बिल्कुल नए सिरे से शुरू करें। टीम के लिए सबसे अधिक राहत भरा, लेकिन यदि किसी उच्च-प्राथमिकता टिकट को अचानक एक नई लंबी घड़ी मिल जाए तो ग्राहकों को ठगा हुआ महसूस हो सकता है।',
            'reopen_heading' => 'जब कोई बंद टिकट फिर से खोला जाए',
            'reopen_intro' => 'यदि कोई टिकट फिर से खोला जाता है (उपयोगकर्ता बंद होने के बाद जवाब देता है):',
            'reopen_reset' => '<strong>Reset (डिफ़ॉल्ट)</strong> &mdash; फिर से खोलने के क्षण से नई प्रतिक्रिया और समाधान घड़ी शुरू करें। फिर से खोलने को व्यावहारिक रूप से एक नए टिकट की तरह मानें।',
            'reopen_continue' => '<strong>Continue</strong> &mdash; बंद होने के समय तक बीते समय से आगे बढ़ें। मूल SLA लक्ष्य लागू रहते हैं।',
            'first_heading' => 'पहली-प्रतिक्रिया की परिभाषा',
            'first_intro' => '"first response" के रूप में क्या गिना जाता है &mdash; वह क्षण जो प्रतिक्रिया घड़ी को रोक देता है?',
            'first_either' => '<strong>Either (डिफ़ॉल्ट)</strong> &mdash; किसी भी तरह की पहली विश्लेषक कार्रवाई: एक आउटबाउंड ईमेल, एक स्थिति परिवर्तन, या एक असाइनमेंट।',
            'first_status' => '<strong>Status change</strong> &mdash; केवल डिफ़ॉल्ट से हटकर किया गया स्थिति परिवर्तन गिना जाता है। अधिक सख्त &mdash; विश्लेषक को टिकट पर वास्तव में काम करना होगा, केवल उसे क्लिक करना काफ़ी नहीं।',
            'first_email' => '<strong>Outbound email</strong> &mdash; केवल अनुरोधकर्ता को भेजा गया ईमेल जवाब गिना जाता है। सबसे सख्त &mdash; ग्राहक को हमारी ओर से जवाब मिलना ही चाहिए।',
            'warn_heading' => 'चेतावनी थ्रेशोल्ड प्रतिशत',
            'warn_body' => 'SLA लक्ष्य में कितना समय बीत जाने पर इंडिकेटर हरे से amber में बदल जाता है। डिफ़ॉल्ट 80% है &mdash; यानी 60 मिनट के प्रतिक्रिया लक्ष्य में 48 मिनट बीतने पर amber दिखता है। यह warning-ट्रिगर उल्लंघन सूचनाओं को भी नियंत्रित करता है।',
        ],
        'breach' => [
            'heading' => 'उल्लंघन सूचनाएँ',
            'sub' => 'प्रति-विभाग कॉन्फ़िगर करने योग्य ईमेल नियम जो तब चलते हैं जब SLA उल्लंघन के करीब पहुँचें (चेतावनी) या वास्तव में उल्लंघन हो जाएँ।',
            'intro' => 'प्रत्येक नियम के चार आयाम होते हैं, सभी स्वतंत्र:',
            'scope_heading' => '1. Scope',
            'scope_body' => 'या तो <strong>Default</strong> (नियम हर विभाग के टिकटों पर लागू होता है) या कोई <strong>विशिष्ट विभाग</strong>। निर्णय: उस विभाग के टिकटों के लिए विभाग-विशिष्ट नियम, डिफ़ॉल्ट पर प्राथमिकता पाता है। बिना डिफ़ॉल्ट नियम के, जिन विभागों का कोई विशिष्ट नियम नहीं है उन्हें कोई सूचना नहीं मिलती।',
            'trigger_heading' => '2. Trigger',
            'trigger_body' => 'या तो <strong>Warning</strong> (टिकट चेतावनी थ्रेशोल्ड पार कर चुका है &mdash; संभावित उल्लंघन) या <strong>Breach</strong> (टिकट ने अपना लक्ष्य पार कर लिया है &mdash; वास्तविक उल्लंघन)। हर एक अपने आप में एक अलग नियम है, इसलिए आप हर एक के लिए अलग लोगों को सूचित कर सकते हैं।',
            'target_heading' => '3. Target',
            'target_body' => 'किस घड़ी पर नज़र रखनी है &mdash; <strong>Response</strong>, <strong>Resolution</strong>, या <strong>Both</strong>।',
            'recip_heading' => '4. Recipients',
            'recip_intro' => 'इनमें से किसी भी संयोजन:',
            'recip_assignee' => '<strong>टिकट का असाइनी</strong> &mdash; वह विश्लेषक जिसके पास वर्तमान में टिकट है। यदि कोई असाइन नहीं है तो छोड़ दिया जाता है।',
            'recip_teams' => '<strong>टिकट के विभाग की टीमों के सदस्य</strong> &mdash; टिकट के विभाग से जुड़ी किसी भी टीम का हर विश्लेषक। यह पूरी कतार को कवर करता है, बिना किसी डिस्ट्रीब्यूशन लिस्ट को बनाए रखे।',
            'recip_specific' => '<strong>कोई विशिष्ट विश्लेषक</strong> &mdash; "SLA champion" / "service manager" पैटर्न, जहाँ यह किसी भूमिका की बजाय एक नामित व्यक्ति होता है।',
            'recip_custom' => '<strong>Custom ईमेल पते</strong> &mdash; कॉमा से अलग किया गया फ़्री-टेक्स्ट। शेयर्ड इनबॉक्स (<code>sla-alerts@company.com</code>), Slack/Teams ईमेल ब्रिज, या डिस्ट्रीब्यूशन लिस्ट के लिए उपयोगी।',
            'tip' => 'हर टिकट प्रति (target, trigger) अधिकतम एक ईमेल भेजता है &mdash; cron worker <code>sla_notifications_sent</code> तालिका में यह ट्रैक करता है कि क्या भेजा जा चुका है। इसलिए एक चेतावनी एक ही बार भेजी जाती है, एक उल्लंघन एक ही बार भेजा जाता है, बस &mdash; कोई स्पैम लूप नहीं।',
            'warn' => '<strong>कोई नियम नहीं = कोई ईमेल नहीं।</strong> भले ही सिस्टम का हर टिकट उल्लंघन में चला जाए, जब तक आप कम से कम एक नियम नहीं जोड़ते तब तक कुछ नहीं भेजा जाता। सब कुछ कवर करने के लिए Default-scope वाली Warning + Breach जोड़ी से शुरुआत करें।',
        ],
        'cron' => [
            'heading' => 'Cron job सेट करना',
            'sub' => 'breach-check स्क्रिप्ट को एक तय शेड्यूल पर चलना होता है। हर 5 मिनट में एक बार सबसे उपयुक्त है।',
            'p1' => 'UI में दिखने वाले SLA इंडिकेटर (इनबॉक्स पर pills, रीडिंग पेन में पैनल) पेज लोड होते ही तुरंत गणना किए जाते हैं। लेकिन उल्लंघन ईमेल तभी भेजी जा सकती हैं जब <em>कोई चीज़</em> सक्रिय रूप से टिकटों की जाँच करे, तब भी जब कोई उन्हें देख नहीं रहा हो। वह चीज़ एक शेड्यूल्ड टास्क है &mdash; Windows पर Task Scheduler; Linux पर cron।',
            'p2' => 'यह स्क्रिप्ट FreeITSM इंस्टॉल डायरेक्टरी में <code>cron/sla_breach_check.php</code> पर है। इसे दो तरीकों से चलाया जा सकता है:',
            'cli_heading' => 'A. CLI (आपके नियंत्रण वाले सर्वर पर अनुशंसित)',
            'cli_note' => 'किसी प्रमाणीकरण की ज़रूरत नहीं &mdash; फ़ाइलसिस्टम अनुमतियाँ पहले से तय करती हैं कि इसे कौन चला सकता है।',
            'http_heading' => 'B. HTTP (शेयर्ड होस्टिंग या रिमोट शेड्यूलर के लिए)',
            'http_note' => 'टोकन पहली इंस्टॉल पर अपने आप बन जाता है और <code>system_settings</code> में <code>sla_cron_token</code> कुंजी के तहत संग्रहीत रहता है (32 hex अक्षर, ~128 बिट एंट्रॉपी)। यह एट-रेस्ट एन्क्रिप्टेड है, इसलिए पंक्ति को सीधे पढ़ने पर आपको टोकन की बजाय <code>ENC:…</code> मिलेगा। अपना टोकन यहाँ से पाएँ:',
            'win_heading' => 'Windows Task Scheduler',
            'win_intro' => 'Task Scheduler खोलें (<code>taskschd.msc</code>) और इन सेटिंग्स के साथ एक नया टास्क बनाएँ:',
            'tbl_field' => 'फ़ील्ड',
            'tbl_value' => 'वैल्यू',
            'win_r1_k' => 'Name',
