            'linux_heading' => 'Linux cron',
            'linux_intro' => 'अपने crontab में एक लाइन जोड़ें (<code>crontab -e</code>):',
            'sec_heading' => 'सुरक्षा &mdash; HTTP endpoint की सुरक्षा कैसे होती है',
            'sec_intro' => 'तीन परतें, सभी स्वचालित रूप से लागू:',
            'sec_token' => '<strong>1. Shared-secret token</strong> &mdash; प्रति इंस्टॉल 128-बिट रैंडम, टाइमिंग अटैक रोकने के लिए constant-time मिलान से जाँचा जाता है।',
            'sec_lockout' => '<strong>2. Per-IP failed-auth lockout</strong> &mdash; पिछले एक घंटे में एक ही IP से 10 से ज़्यादा गलत-टोकन प्रयास 1 घंटे का 429 लॉकआउट ट्रिगर करते हैं। fail2ban की ज़रूरत के बिना ब्रूट-फ़ोर्स प्रयासों को विफल करता है।',
            'sec_interval' => '<strong>3. सफल रन के बीच न्यूनतम अंतराल</strong> &mdash; <code>sla_cron_min_interval_seconds</code> (डिफ़ॉल्ट 30s)। यदि पिछले सफल रन के बाद इससे जल्दी कोई वैध-टोकन रिक्वेस्ट भी आती है, तो उसे 429 मिलता है। यह गलती से दोहरे शेड्यूलिंग और रनअवे लूप को रोकता है।',
            'log_heading' => 'गतिविधि लॉग',
            'log_body' => 'हर इनवोकेशन (स्वीकृत या अस्वीकृत) <code>sla_cron_runs</code> तालिका में समय, परिणाम, गिनती और क्लाइंट IP के साथ लॉग होता है। SLA सेटिंग्स टैब के नीचे <strong>Cron Activity</strong> पैनल में पिछले 20 रन देखें &mdash; यह पुष्टि करने के लिए उपयोगी है कि शेड्यूल चल रहा है और किसी भी विफल-प्रमाणीकरण प्रयास की जाँच के लिए। <code>sla_cron_log_retention_days</code> (डिफ़ॉल्ट 30) के बाद पंक्तियाँ अपने आप हटा दी जाती हैं ताकि तालिका छोटी बनी रहे।',
        ],
        'examples' => [
            'heading' => 'व्यावहारिक उदाहरण',
            'sub' => 'सरल सिंगल-टाइमज़ोन मामले से लेकर जटिल क्रॉस-टाइमज़ोन मामले तक, जहाँ "निष्पक्ष" को परिभाषित करना ज़रूरी हो जाता है।',
            'ex1_heading' => 'उदाहरण 1: टिकट UK में उठाया गया, सर्विस डेस्क भी UK में',
            'ex1_title' => 'सरल मामला',
            'ex1_tag' => 'single timezone',
            'ex1_setup' => '<strong>Setup:</strong> एक व्यावसायिक कैलेंडर, नाम <em>UK Office</em>, timezone <code>Europe/London</code>, Mon-Fri 09:00-17:00, कोई अवकाश नहीं। P2 प्राथमिकता का प्रतिक्रिया लक्ष्य 1 घंटा और समाधान लक्ष्य 4 घंटे है, दोनों <em>UK Office</em> कैलेंडर के अनुसार चलते हैं।',
            'ex1_scenario' => '<strong>Scenario:</strong> उपयोगकर्ता <strong>बुधवार को 16:30 UK</strong> पर एक P2 टिकट उठाता है।',
            'ex1_timeline' => 'बुध 16:30 UK &mdash; <strong>टिकट बना</strong>, प्रतिक्रिया घड़ी शुरू।
बुध 17:00 UK &mdash; ऑफिस बंद, घड़ी रुकी (60 मिनट के लक्ष्य में से 30 मिनट उपयोग)।
गुरु 09:00 UK &mdash; ऑफिस खुला, घड़ी फिर से चली।
गुरु 09:30 UK &mdash; विश्लेषक जवाब देता है। प्रतिक्रिया SLA ठीक अंतिम क्षण में पूरा हुआ (60 मिनट उपयोग, 60 मिनट लक्ष्य)।',
            'ex1_outro' => 'यदि विश्लेषक <strong>गुरुवार 10:00 UK</strong> तक जवाब न देता, तो प्रतिक्रिया <strong>30 मिनट से उल्लंघन</strong> हो जाती (60 मिनट के लक्ष्य के मुक़ाबले 90 मिनट उपयोग &mdash; बुधवार शाम से 30, गुरुवार सुबह से 60)। 1 घंटे की घड़ी केवल व्यावसायिक घंटों में चलती है, लेकिन दिन के अंत में आया टिकट फिर भी ऑफिस दोबारा खुलने पर अपने अधिकांश बजट को रात भर में खर्च कर देता है &mdash; 09:00 बजे पहुँचने वाले विश्लेषक के लिए यह मान लेना आसान है कि उसके पास पूरा घंटा है, जबकि वास्तव में केवल 30 मिनट बचे होते हैं।',
            'ex2_heading' => 'उदाहरण 2: टिकट UK में उठाया गया, सर्विस डेस्क एस्टोनिया में',
            'ex2_title' => 'क्रॉस-टाइमज़ोन मामला',
            'ex2_tag' => '"निष्पक्ष" को परिभाषित करने के 3 तरीके',
            'ex2_setup' => '<strong>Setup:</strong> UK ग्राहक (<code>Europe/London</code>, GMT/BST), एस्टोनिया सर्विस डेस्क (<code>Europe/Tallinn</code>, EET/EEST &mdash; <strong>UK से 2 घंटे आगे</strong>)। दोनों डेस्क नाममात्र रूप से स्थानीय समय के अनुसार 09:00-17:00 काम करते हैं।',
            'ex2_scenario' => '<strong>Scenario:</strong> UK ग्राहक <strong>शुक्रवार को 16:30 UK</strong> पर एक P2 टिकट उठाता है (= 18:30 एस्टोनिया, एस्टोनिया बंद होने के बाद)। एस्टोनिया विश्लेषक के लिए इस पर काम करने का अगला मौका सोमवार 09:00 एस्टोनिया (= 07:00 UK) है। प्रतिक्रिया लक्ष्य 1 घंटा है।',
            'ex2_question' => 'SLA को क्या कहना चाहिए? इसके तीन तर्कसंगत उत्तर हैं, हर एक अपने-अपने तरीके से निष्पक्ष। आप यह चुनते हैं कि प्राथमिकता को कौन सा कैलेंडर सौंपना है, इस आधार पर कि आपका सर्विस कॉन्ट्रैक्ट क्या वादा करता है।',
            'optA_label' => 'Option A &mdash; ग्राहक-केंद्रित',
            'optA_p1' => '<strong>प्राथमिकता को <em>UK</em> घंटों वाला कैलेंडर उपयोग करने के लिए सेट करें।</strong> विश्लेषक चाहे कहीं भी हो, घड़ी UK 09:00-17:00 के अनुसार चलती है।',
            'optA_p2' => 'ऊपर के परिदृश्य में, टिकट शुक्रवार 16:30 UK पर उठाया गया: घड़ी शुक्रवार 16:30&ndash;17:00 UK चलती है (30 मिनट उपयोग), रात भर + वीकेंड रुकती है, सोमवार 09:00 UK पर फिर से चलती है। यदि कोई एस्टोनिया विश्लेषक सोमवार 10:00 एस्टोनिया (= 08:00 UK) पर जवाब देता है, तो UK कैलेंडर तब भी रुका हुआ है (UK ऑफिस 09:00 UK पर खुलता है), इसलिए कोई अतिरिक्त मिनट नहीं जुड़ता &mdash; उपयोग 30 मिनट पर ही रहता है। <strong>SLA 30 मिनट के मार्जिन से पूरा हुआ</strong>। 09:30 UK (= 11:30 एस्टोनिया) के बाद कोई भी जवाब उल्लंघन होगा।',
            'optA_p3' => '<em>किसके लिए निष्पक्ष:</em> ग्राहक के लिए। उनका अनुभव उनके कार्य-दिवस से मेल खाता है।<br><em>ट्रेड-ऑफ:</em> एस्टोनिया के विश्लेषकों से 09:00-17:00 UK समय (= 11:00-19:00 एस्टोनिया) उपलब्ध रहने की अपेक्षा की जाती है, जिससे उनका कार्य-दिवस 2 घंटे बढ़ जाता है।',
            'optB_label' => 'Option B &mdash; विश्लेषक-केंद्रित',
            'optB_p1' => '<strong>प्राथमिकता को <em>एस्टोनिया</em> घंटों वाला कैलेंडर उपयोग करने के लिए सेट करें।</strong> घड़ी एस्टोनिया 09:00-17:00 के अनुसार चलती है।',
            'optB_p2' => 'वही परिदृश्य: टिकट शुक्रवार 18:30 एस्टोनिया (बंद होने के बाद) उठाया गया, घड़ी पूरे वीकेंड रुकी रहती है, सोमवार 09:00 एस्टोनिया (= 07:00 UK) से चलना शुरू करती है। यदि विश्लेषक सोमवार 09:30 एस्टोनिया (= 07:30 UK) पर जवाब देता है, तो प्रतिक्रिया SLA ने 60 मिनट के लक्ष्य में से 30 मिनट उपयोग किए &mdash; <strong>30 मिनट के मार्जिन से पूरा हुआ</strong>। UK ग्राहक ने शुक्रवार 16:30 UK पर टिकट उठाया और सोमवार 07:30 UK पर जवाब पाया &mdash; उनका वॉल-क्लॉक इंतज़ार SLA के संकेत से कहीं ज़्यादा लंबा था।',
            'optB_p3' => '<em>किसके लिए निष्पक्ष:</em> विश्लेषकों के लिए। वे सामान्य घंटों में काम करते हैं।<br><em>ट्रेड-ऑफ:</em> UK के ग्राहकों को लग सकता है कि SLA "झूठ बोल रहा है" यदि शुक्रवार दोपहर का टिकट सोमवार सुबह एस्टोनिया समय तक स्वीकार न हो, लेकिन रिपोर्ट कहती है कि प्रतिक्रिया SLA 1 घंटे का था। सुनिश्चित करें कि आपका सर्विस कॉन्ट्रैक्ट स्पष्ट रूप से कहता हो कि SLA सपोर्ट-डेस्क के घंटों के अनुसार चलता है।',
            'optC_label' => 'Option C &mdash; ओवरलैप विंडो (सबसे सख्त)',
            'optC_p1' => '<strong>प्राथमिकता को केवल उन घंटों को कवर करने वाला कैलेंडर उपयोग करने के लिए सेट करें जब दोनों डेस्क खुले हों।</strong> UK 09:00-17:00, एस्टोनिया 09:00-17:00 (= UK 07:00-15:00) से <strong>UK 09:00-15:00 विंडो</strong> में ओवरलैप करता है &mdash; प्रति कार्य-दिवस 6 घंटे।',
            'optC_p2' => 'वही परिदृश्य: टिकट शुक्रवार 16:30 UK पर उठाया गया (ओवरलैप के बाहर, क्योंकि ओवरलैप 15:00 UK पर बंद हो जाता है), घड़ी वीकेंड भर रुकी रहती है, सोमवार 09:00 UK (= 11:00 एस्टोनिया, वह क्षण जब ओवरलैप फिर खुलता है) पर फिर से चलती है। यदि एस्टोनिया विश्लेषक 11:30 एस्टोनिया (= 09:30 UK) पर जवाब देता है, तो प्रतिक्रिया SLA ने 60 मिनट के लक्ष्य में से 30 मिनट उपयोग किए &mdash; <strong>30 मिनट के मार्जिन से पूरा हुआ</strong>। जवाब ओवरलैप विंडो के दौरान आया, इसलिए यह तुरंत गिना जाता है।',
            'optC_p3' => '<em>किसके लिए निष्पक्ष:</em> दोनों पक्षों के लिए &mdash; SLA केवल उन घंटों में चलता है जब डेस्क वास्तव में टिकट पर काम बढ़ा सकता है AND ग्राहक जवाब पाने के लिए अपनी डेस्क पर मौजूद होता है।<br><em>ट्रेड-ऑफ:</em> कम दैनिक विंडो का मतलब है कि आक्रामक लक्ष्य पूरे करने में वॉल-क्लॉक समय ज़्यादा लगता है। 4 घंटे का समाधान लक्ष्य ओवरलैप के 1.5 दिनों तक फैल जाता है, जबकि सामान्य 8 घंटे के कैलेंडर में यह एक ही दिन में पूरा हो जाता।',
            'choose_tip' => '<strong>कैसे चुनें:</strong> अपना सर्विस कॉन्ट्रैक्ट देखें। यदि उसमें लिखा है "प्राप्ति के 1 घंटे के भीतर प्रतिक्रिया" &mdash; तो यह Option A है (ग्राहक की घड़ी)। यदि लिखा है "1 कार्य-घंटे के भीतर प्रतिक्रिया" &mdash; तो आमतौर पर यह Option B है (जो भी डेस्क काम कर रही हो)। यदि लिखा है "आपसी उपलब्धता के 1 घंटे के भीतर" &mdash; तो यह Option C है। यदि कोई कॉन्ट्रैक्ट नहीं है, तो टीम से पूछें: क्या आप एस्टोनिया के घंटों के बाहर भी दबाव महसूस करना चाहते हैं (Option A), या क्या आप चाहते हैं कि UK ग्राहक कभी-कभी नज़रअंदाज़ महसूस करें (Option B)?',
            'ex3_heading' => 'उदाहरण 3: वेंडर के इंतज़ार के दौरान घड़ी रोकना',
            'ex3_title' => 'पॉज़ स्थितियाँ व्यवहार में कैसे काम करती हैं',
            'ex3_tag' => 'pause-the-clock',
            'ex3_setup' => '<strong>Setup:</strong> P3 प्राथमिकता, 8 व्यावसायिक-घंटे का समाधान लक्ष्य, UK कैलेंडर, स्थिति "Awaiting Vendor" <em>Pause SLA</em> के रूप में चिह्नित।',
            'ex3_scenario' => '<strong>Scenario:</strong> टिकट सोमवार 09:00 UK पर उठाया गया। विश्लेषक सोमवार 11:00 UK पर Microsoft को एस्केलेट करता है और टिकट को "Awaiting Vendor" में ले जाता है। Microsoft बुधवार 14:00 UK पर जवाब देता है। विश्लेषक फिक्स लागू करता है और गुरुवार 10:00 UK पर टिकट बंद करता है।',
            'ex3_timeline' => 'सोम 09:00 &mdash; टिकट बना, समाधान घड़ी चल रही है।
सोम 11:00 &mdash; "Awaiting Vendor" में ले जाया गया, <strong>घड़ी रुकी</strong> (2 घंटे उपयोग)।
बुध 14:00 &mdash; वापस "In Progress" में लाया गया, <strong>घड़ी फिर से चली</strong>।
बुध 17:00 &mdash; ऑफिस बंद (कुल 5 घंटे उपयोग)।
गुरु 09:00 &mdash; ऑफिस खुला।
गुरु 10:00 &mdash; टिकट बंद (कुल 6 घंटे उपयोग)। 8 घंटे के लक्ष्य के मुक़ाबले <strong>SLA पूरा हुआ</strong>।',
            'ex3_outro' => 'वॉल-क्लॉक समय: ~3 दिन। SLA समय: 6 कार्य-घंटे। pause-status फ़्लैग के बिना, SLA वेंडर के इंतज़ार के पूरे 2 दिन + व्यावसायिक घंटे गिनता, जो कुल मिलाकर ~18 कार्य-घंटे होते &mdash; यानी काफ़ी हद तक उल्लंघन।',
        ],
        'trouble' => [
            'heading' => 'समस्या निवारण',
            'sub' => 'सामान्य समस्याएँ और क्या जाँचें।',
            'col_symptom' => 'लक्षण',
